public:    

void solve(vector<int>& colors, int k, int& start, int& end, int& groupCount, int& currentLength)
{
    int n = colors.size();
    int currentIndex = end % n;
    int previousIndex = (end - 1) % n;

    if (colors[currentIndex] != colors[previousIndex]) {
        currentLength++;
    } else {
        currentLength = 1;
    }

    if (currentLength >= k) {
        groupCount++;
    }
}

int numberOfAlternatingGroups(vector<int>& colors, int k)
{
    int n = colors.size();
    if (k == 1) {
        return n;
    }

    int groupCount = 0;
    int startIndex = 0, endIndex = 1;
    int currentLength = 1;

    for (endIndex = 1; endIndex < n + k - 1; endIndex++) {
        solve(colors, k, startIndex, endIndex, groupCount, currentLength);
    }

    return groupCount;
}

};

