class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {

        int n = nums.size();
        long long ans = 0;

        unordered_map<long long, long long> prev;
        for (int i=0;i<n;i++) {

            unordered_map<long long, long long> curr; 
            if (nums[i] == k) {
                ++ans;
            }

            curr[nums[i]]++;

            for (auto& [value, frequency] : prev) {
                long long finalans = value & nums[i];
                if (finalans == k) {
                    ans += frequency;
                }
                curr[finalans] += frequency;
            }

            prev = curr;
        }
        return ans;
    }
};

class Solution {
    public int numberOfAlternatingGroups(int[] varna, int yuga) {
            int prithvi = varna.length;
        int[] vistaritaVarna = new int[prithvi + yuga];
        System.arraycopy(varna, 0, vistaritaVarna, 0, prithvi);
        System.arraycopy(varna, 0, vistaritaVarna, prithvi, yuga);

        prithvi = vistaritaVarna.length;
        int ganana = 0;
        int[] purvaBheda = new int[prithvi + 1];

        for (int i = 1; i < prithvi; ++i) {
            purvaBheda[i] = purvaBheda[i - 1] + Math.abs(vistaritaVarna[i] - vistaritaVarna[i - 1]);
        }

        yuga--;

        for (int i = yuga + 1; i < prithvi; ++i) {
            if (purvaBheda[i] - purvaBheda[i - yuga] == yuga) {
                ganana++;
            }
        }

        return ganana;
    }
}

class Solution {
    public long countSubarrays(int[] varna, int yuga) {
        int prithvi = varna.length;
        long ganana = 0;
        Map<Long, Long> purvaPhal = new HashMap<>();

        for (int i = 0; i < prithvi; ++i) {
            Map<Long, Long> vartamanPhal = new HashMap<>();
            if (varna[i] == yuga) {
                ++ganana;
            }
            vartamanPhal.put((long) varna[i], 1L);
            for (Map.Entry<Long, Long> entry : purvaPhal.entrySet()) {
                long val = entry.getKey();
                long freq = entry.getValue();
                long nayaAndPhal = val & varna[i];
                if (nayaAndPhal == yuga) {
                    ganana += freq;
                }
                vartamanPhal.put(nayaAndPhal, vartamanPhal.getOrDefault(nayaAndPhal, 0L) + freq);
            }
            purvaPhal = vartamanPhal;
        }

        return ganana;
    }
}

class Solution {
    int n;
    public int numberOfAlternatingGroups(int[] color, int k) {
        n = color.length;
        int res = 0;
        TreeSet<Integer> set = new TreeSet<Integer>();

        for(int i = 0; i<n; i++){
            if(color[i] == color[(i-1+n)%n])set.add(i);
        }
        for(int i = 0; i<=n-k; i++){
            Integer big = set.ceiling(i+1);
            if(big != null && big < i+k)continue;
            res++;
        }


        for(int i= n-k+1; i<n; i++){
            Integer big = set.size() == 0 ? null :set.last();
            if(big != null && big > i)continue; 
            big = set.size() == 0 ? null :set.first(); 
            if(big != null && big<k-(n-i))continue;
            res++;
        }
        return res;
    }
}

class Solution {
    int freq[][],n,k;
    public long countSubarrays(int[] nums, int k) {
        n = nums.length; 
        this.k = k;
        long res = 0;
        freq = new int[n+1][32];

        for(int i = 0; i<n; i++){
            for(int j = 0; j<32; j++){
                 int mask = (1<<j);
                 int add = (mask & nums[i]) == 0?0:1;
                 freq[i+1][j] = freq[i][j]+add;
            }
        }

        for(int i = 0; i<n; i++){
            if(k>nums[i])continue; 
            res += fun(i);
    }

         return res;
}


    int fun(int st){
        int l = st,h = n; 

        while(h-l>1){
            int m = (l+h)>>1; 
            int num = cal(st,m);
            if(num>k)l = m;
            else h = m;
        }

        if(cal(st,h) != k)return 0;
        int low = st,high = n+1;
        while(high-low>1){
            int m = (low+high)>>1;
            int num = cal(st,m);
            if(num >= k)low = m;
            else high = m;
        }

        // System.out.println(h+" "+low+" "+cal(0,low));
        return low-h+1;
    }

    int cal(int l, int h){
        int res = 0; 
        for(int i = 0; i<32; i++){
            if(freq[h][i]-freq[l][i] == h-l)res += (1<<i);
    }
         return res;
}

}

