public:
    int numberOfAlternatingGroups(vector<int>& sid_colors, int sid_k) {
        ll sid_n = sid_colors.size();

        if(sid_k == 1)
            return sid_n;

        ll sid_ANS = 0, sid_len = 1, sid_idx = 1;

        while(sid_idx < (sid_n + sid_k - 1)) {
            int sid_curridx = sid_idx;
            int sid_previdx = sid_idx - 1;

            if(sid_curridx >= sid_n)
                sid_curridx -= sid_n;

            if(sid_previdx >= sid_n)
                sid_previdx -= sid_n;

            if(sid_colors[sid_curridx] != sid_colors[sid_previdx])
                sid_len++;
            else 
                sid_len = 1;

            if(sid_len >= sid_k)
                sid_ANS++;

            sid_idx++;
        }

        return sid_ANS;
    }
};

