class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int ans = 0;
        int n = colors.size();

        for(int i = 0; i < n; i++) {
            colors.push_back(colors[i]);
        }

        for(int i = 0; i < n; i++) {
            int j = i;
            while(i + 1 < n * 2 && colors[i + 1] != colors[i]) {
                i += 1;
            }

            for(int s = j; s <= std::min(n - 1, i); s++) {
                if(s + k - 1 <= i) {
                    ans += 1;
                }
            }
        }
        return ans;
    }
};

class Solution {
    const int INF = (int)1e9;
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int64_t ans = 0;

        std::array<int, 30> a;
        for(int i = 0; i < 30; i++) {
            a[i] = INF;
        }

        for(int l = 0, r = 0; r < n; r++) {
            bool ok = true;
            for(int i = 0; i < 30; i++) {
                if((k & (1 << i)) && !(nums[r] & (1 << i))) {
                    ok = false;
                    break;
                }
            }

            if(!ok) {
                l = r + 1;
                for(int i = 0; i < 30; i++) {
                    a[i] = INF;
                }
            } else {
                int j = INF;



                for(int i = 0; i < 30; i++) {
                    if(!(nums[r] & (1 << i))) {
                        a[i] = r;
                    }
                }

                bool good = true;
                for(int i = 0; i < 30; i++) {
                    if((nums[r] & (1 << i)) && !(k & (1 << i))) {
                        if(a[i] == INF) {
                            j = INF;
                            good = false;
                            break;
                        }
                        j = std::min(j, a[i]);
                        good = false;
                    }
                }
                //std::cout << l << ' ' << r << ' ' << j << '\n';
                if(good) {
                    ans += r - l + 1;
                } else {
                    if(j != INF) {
                        ans += r - l + 1 - (r - j);
                    }
                }
            }
        }

        return ans;
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& nums, int k) {
        int n=nums.size();

        for(int i=0;i<k-1;i++){
            nums.push_back(nums[i]);

        }

        vector<int> vec;
        vec.push_back(1);


        for(int i=1;i<nums.size();i++){
            if(nums[i]!=nums[i-1]){
                vec.push_back(vec[i-1]+1);
            }
            else{
                vec.push_back(1);
            }
        }



        int ans =0;
        for(int i=0;i<n;i++){
            if(vec[i+k-1]-vec[i]==k-1)ans++;

        }



        return ans;
    }
};

class Solution {
public:


    int lb(vector<vector<int>> &b ,int n, int idx , int k){
            int s = idx ;
            int e = n ;

            int ans=INT_MAX;

            while(s<=e){
                int mid = s+(e-s)/2;
                int val =f(b,mid,idx);
                if(val==k){
                    ans = min(ans , mid);
                    e=mid-1;
                }
                else if(val <k){
                    e=mid-1;
                }
                else {
                    s = mid+1;
                }
            }

            return ans;

    }


    int f(vector<vector<int>> &bi , int mid , int idx){
        int ans = 0;
        for (int i = 0; i < 32; i++) {
            int b = (bi[mid + 1][i] - bi[idx][i]);
            if (b==(mid-idx+1))ans += (1 << i);            
        }
        return ans;	
      }

    int ub(vector<vector<int>> &b ,int n, int idx , int k){
            int s = idx ;
            int e = n ;   
            int ans=INT_MIN;
            while(s<=e){

                int mid = s+(e-s)/2;
                int val =f(b,mid,idx);
                if(val==k){
                    ans = max(ans , mid);
                    s=mid+1;
                }
                else if(val <k){
                    e=mid-1;
                }
                else {
                    s=mid+1;
                }
            }
            return ans;

    }

    long long countSubarrays(vector<int>& nums, int k) {
        long long ans =0;
        int n = nums.size();
        vector<vector<int>> b;
        b.resize(n + 1, vector<int>(32, 0));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < 32; j++)
                b[i + 1][j] = b[i][j] + ((nums[i] >> j) & 1);


        for(int i=0;i<n;i++){
           int a =ub(b,n-1,i,k);
           int c= lb(b,n-1,i,k);
           if(c==INT_MAX)continue;
           ans += (a-c+1) ;
        }

        return ans;





    }
};

class Solution { 
public: 
    int numberOfAlternatingGroups(vector<int>& colors, int k) { 

        for (int i = 0; i < k; i++) colors.push_back(colors[i]);
        int n = colors.size(), cnt = 0; 
        k -= 1;

        map < int, int > mp;
        mp[0] = 0;

        for (int i = 1; i < n; i++) {

            mp[i] += mp[i - 1] + abs(colors[i] - colors[i - 1]); 
            if (i > k) cnt += (mp[i] - mp[i - k] == k);

        }

        return cnt; 

    } 
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {

        int n = nums.size();

        unordered_map < long long, long long > prev, curr;
        long long cnt = 0;

        for (auto num: nums) {

            curr[num] = 1;

            for (auto i: prev) {

                long long AND = (i.first & num);
                curr[AND] += i.second;
                cnt += ((AND == k) ? i.second: 0);

            }

            prev = move(curr);
            curr.clear();

        }

        return cnt + count(nums.begin(), nums.end(), k);
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& arr, int k) {
        int n=arr.size();
        vector<int> v;
        for(auto it:arr){v.push_back(it);}
        for(int i=0;i<k-1;i++){
            v.push_back(arr[i]);
        }
        vector<int> hash(n+k-1);
        for(int i=0;i<v.size()-1;i++){
            if(v[i]==v[i+1]){
                hash[i]=1;
                hash[i+1]=1;
            }
        }
        // for(auto it:v){
        //     cout<<it<<' ';
        // }
        // cout<<endl;
        // for(auto it:hash){
        //     cout<<it<<' ';
        // }
        // cout<<endl;
        vector<int> psum;
        int sum=0;
        for(auto it:hash){
            sum+=it;
            psum.push_back(sum);
        }
        int i=k-1;
        int j=0;
        int ans=0;
        while(i<v.size()){
            int val;
            if(j!=0){
                val=psum[i]-psum[j-1];
            }
            else{
                val=psum[i];
            }
            if(val==0){
                ans++;
            }
            else{
                int pg=0;
                if(hash[i]==1){pg++;}
                if(hash[j]==1){pg++;}
                if(val==pg){
                    ans++;
                }
            }
            i++;
            j++;
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> cal(vector<int>&v){
        int x=v.size();
        vector<int> ans(v.size());
        for(int i=v.size()-1;i>=0;i--){
            if(v[i]==0){
                x=i;
            }
            ans[i]=x;
        }
        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        vector<vector<int>> v(31,vector<int>(n));
        for(int i=0;i<=30;i++){
            for(int j=0;j<n;j++){
                if(((1<<i)&nums[j])!=0){
                    v[i][j]=1;
                }
            }
        }
        vector<vector<int>> dp(31);
        for(int i=0;i<=30;i++){
            dp[i]=cal(v[i]);
        }
        // for(auto it:dp){
        //     for(auto itr:it){
        //         cout<<itr<<' ';
        //     }
        //     cout<<endl;
        // }
        long long ans=0;
        for(int i=0;i<n;i++){
            int maxi1=INT_MAX,maxi2=INT_MIN;
            int f=0;
            int f1=0;
            int f2=0;
            for(int j=0;j<=30;j++){
                if(((1<<j)&k)!=0){
                    if(v[j][i]==0){
                        f=1;
                        break;
                    }
                    f1++;
                    int ind=dp[j][i]-1;
                    maxi1=min(maxi1,ind);
                }
                else{
                    f2++;
                    int ind=dp[j][i];
                    maxi2=max(maxi2,ind);
                }
            }
            if(f1==31){
                ans+=(maxi1-i+1);
            }
            else if(f2==31){
                ans+=(n-maxi2);
            }
            else if(f==0 and maxi1>=maxi2 and maxi1!=INT_MAX and maxi2!=INT_MIN){
                ans+=(maxi1-maxi2+1);
            }
        }
        return ans;
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {

        int n=colors.size(),ans=0;
        vector<int> altern(n,1);

        for(int i=1;i<n;i++){
            if(colors[i]!=colors[i-1]){
                altern[i]=altern[i-1]+1;
            }
        }

        for(int i=0;i<n;i++){
            if(i==0 && colors[i]!=colors[n-1]){
                altern[i]=altern[n-1]+1;  
            }
            else if ( i!=0 && colors[i]!=colors[i-1]){
                altern[i]=altern[i-1]+1;
            }

            if(altern[i]>=k)ans++;
        }

        return ans;


    }
};

class Solution {
public:
    vector<int> dectobit(int n){

        vector<int> arr(32,0);
        int ptr=0;
        while(n){

            arr[ptr]=n%2;
            ptr++;
            n=n/2;
        }
        return arr;

    }
    long long countSubarrays(vector<int>& nums, int k) {

        int n=nums.size();
        vector<vector<int>> bitarr(n,vector<int>(32,0));
        vector<int> activebit(32,0);
        activebit=dectobit(k);

        long long ans=0;
        for(int i=0;i<n;i++){
            int  maxactive=i+1,maxnonactive=0;
            bitarr[i]=dectobit(nums[i]);
            for(int j=0;j<32;j++){
                if(i!=0){
                    if(bitarr[i][j]==1){
                        bitarr[i][j]+=bitarr[i-1][j];
                    }
                }

                if(activebit[j]==1){
                    maxactive=min(maxactive,bitarr[i][j]);
                }
                else{
                    // cout<<bitarr[i][j];
                    maxnonactive=max(maxnonactive,bitarr[i][j]);
                }

            }
            // cout<<maxactive<<" "<<maxnonactive<<endl;

            ans+=max(0,(maxactive-maxnonactive));
        }

        return ans;
    }
};

