class Solution {
    public int numberOfAlternatingGroups(int[] C, int k) {
        int n = C.length;
        int R = 0;
        int N = 1;
        int z=0;
        int[] extendedC = new int[n + k - 1];
        System.arraycopy(C, 0, extendedC, 0, n);
        System.arraycopy(C, 0, extendedC, n, k - 1);

        for (int i = 1; i < extendedC.length; i++) {
            if (extendedC[i] != extendedC[i - 1]) {
                N++;
            } else {
                N = 1;
                z++;
            }
            if (N >= k) {
                R++;
                z--;
            }
        }

        return R;

    }
}

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        for (int i = 0; i < k - 1; i++) {
            colors.push_back(colors[i]);
        }
        int n = colors.size();
        vector<int> prefixIndex(n, 0);
        prefixIndex[0] = 0;
        for (int i = 1; i < n; i++) {
            if (colors[i - 1] != colors[i]) {
                prefixIndex[i] = prefixIndex[i - 1];
            } else {
                prefixIndex[i] = i;
            }
        }
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (i - prefixIndex[i] + 1 >= k) {
                count++;
            }
        }
        return count;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long c = 0;
        int z=0;
        Map<Long, Long> ans = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            Map<Long, Long> tempans = new HashMap<>();

            if (nums[i] == k) {
                c++;
                z--;
            }
            tempans.put((long)nums[i], 1L);
            z++;

            for (Map.Entry<Long, Long> entry : ans.entrySet()) {
                long val = entry.getKey();
                long freq = entry.getValue();
                long newand = val & nums[i];
                if (newand == k) {
                    c += freq;
                }
                tempans.put(newand, tempans.getOrDefault(newand, 0L) + freq);
                z++;
            }

            ans = tempans;
        }

        return c;
    }
}

