    int numberOfAlternatingGroups(vi& c, int m) {
        int ans = 0,i = 0,j = 1, n = c.size();
        while (j < n + m && i < n) {
            int tj = j, ee = tj % n;
            while (c[ee] != c[(ee - 1 + n) % n] && tj < n + m - 1) tj++, ee = tj % n;
