class Solution {
public:
    ll countSubarrays(vi& numbers, int key) {
        int length = numbers.size();
        ll totalCount = 0;

        umpii previousResults;
        int position = 0;

        while (position < length) {
            umpii currentResults;

            if (numbers[position] == key) {
                ++totalCount;
            }
            currentResults[numbers[position]] = 1;

            for (auto& [prevValue, frequency] : previousResults) {
                ll newAndValue = prevValue & numbers[position];
                if (newAndValue == key) {
                    totalCount += frequency;
                }
                currentResults[newAndValue] += frequency;
            }

            previousResults = currentResults;
            ++position;
        }

        return totalCount;
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& tiles, int groupSize) {
        int numTiles = tiles.size(); 
        int totalCount = 0; 

        if (groupSize == 1) { 
            return numTiles; 
        } 

        int currentLength = 1; 
        int index = 1; 
        while (index < numTiles + groupSize - 1) { 
            int currPos = index; 
            int prevPos = index - 1; 

            if (currPos >= numTiles) { 
                currPos -= numTiles; 
            } 
            if (prevPos >= numTiles) { 
                prevPos -= numTiles; 
            } 

            if (tiles[currPos] != tiles[prevPos]) { 
                ++currentLength; 
            } else { 
                currentLength = 1; 
            } 

            if (currentLength >= groupSize) { 
                ++totalCount; 
            } 

            ++index; 
        } 

        return totalCount; 
    }
};

