class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();
        int i = 0, count = 0, curr_col = colors[0], curr_cnt = 1;
        int pos = 1;
        set <pair <int, int>> st;
        while (pos < 2 * n) {
            int j = pos % n;
            if (colors[j] == curr_col ^ 1) {
                curr_cnt++;
                curr_col ^= 1;
            } else {
                i = j;
                curr_cnt = 1;
                curr_col = colors[j];
            }
            while (curr_cnt > k) {
                curr_cnt--;
                i++;
            }
            if (curr_cnt == k) {
                st.insert({i % n, j});
            }
            pos++;
        }
        // for (auto it : st) {
        //     cout << it.first << " " << it.second << endl;
        // }
        return st.size();
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int const n = colors.size();
        // // corner case
        // if(n == k){
        //     colors.push_back(colors[0]);
        //     for(int i=0; i<n; i++){
        //         if(colors[i] == colors[i+1]){ return 0; }
        //         return 1;
        //     }
        // }

        colors.reserve(n + k - 1);
        for(int i=0; i<k-1; i++){
            colors.push_back(colors[i]);
        }
        vector<int> alters(colors.size(), 1);
        for(int j = colors.size()-2; j >= 0; j--){
            if(colors[j] != colors[j+1]){
                alters[j] += alters[j+1];
            }
        }

        int ans = 0;
        for(int i=0; i<n; i++){ // i: group head
            if(alters[i] >= k){ ans++; }
        }
        return ans;
    }
};

