class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
      int n=colors.size();
      int m=n;
      vi a;
      for(int i=0;i<2*n;++i){
        if(i<n){
          a.pb(colors[i]);
        }
        else{
          a.pb(colors[i-n]);
        }
      }
      int cnt=0;
      n=a.size();
      vvi odd(n,vi(2,0)),even(n,vi(2,0));
      for(int i=0;i<n;++i){
        if(i%2){
            if(i-2>=0){
                odd[i]=odd[i-2];
            }
          odd[i][a[i]]++;
        }
        else{
          if(i-2>=0){
            even[i]=even[i-2];
            }
          even[i][a[i]]++;
        }
      }
      for(int i=k-1;i<m+k-1;++i){
          if(a[i]==a[i-1])  continue;
        int st=i-(k-1);
        int up=((st%2==i%2)?2:1),up2=3-up;
        if(i%2){
          int x=odd[i][a[i]]-(st-up>=0?odd[st-up][a[i]]:0);
          int y=even[i-1][a[i-1]]-(st-up2>=0?even[st-up2][a[i-1]]:0);
          if((x+y)==k){
            cnt++;
          }
        }
        else{
          int x=even[i][a[i]]-(st-up>=0?even[st-up][a[i]]:0);
          int y=odd[i-1][a[i-1]]-(st-up2>=0?odd[st-up2][a[i-1]]:0);
          if((x+y)==k){
            cnt++;
          }
        }
      }
      return cnt;
    }
};

