class Solution {
public:
    long long countSubarrays(vector<int>& v, int k) {
      ll n=v.size();
      vvi mark(32,vi(n,0));
      for(ll i=31;i>=0;--i){
        for(ll j=0;j<n;++j){
          ll b=(v[j]>>i)&1;
          mark[i][j]=b;
        }
      }
      vvi prv(32,vi(n,-1));
      for(ll i=31;i>=0;--i){
        ll zro=-1;
        for(ll j=0;j<n;++j){
          prv[i][j]=zro;
          if(mark[i][j]==0){
            zro=j;
          }
        }
      }
      ll cnt=0;
      for(ll i=0;i<n;++i){
        ll rmn=i,lmx=0,curr=1;
        for(ll j=0;j<32;++j){
          ll zro=prv[j][i];
          ll have=mark[j][i];
          ll b=(k>>j)&1;
          if(!b){
            if(have){
              if(lmx>zro) {
                curr=0;break;
              }
              rmn=min(rmn,zro);
            }
          }
          else{
            if(have){
              if(rmn<zro) {
                curr=0;break;
              }
              lmx=max(lmx,zro+1);
            }
            else{
              curr=0;
              break;
            }
          }
        }
        if(!curr)   continue;
        cnt+=(rmn-lmx+1);
      }
      return cnt;
    }
};

def number_of_alternating_groups(c, k):
    n = len(c)
    ans = 0
    dp = [0] * n
    dp[0] = 1

    for i in range(1, n):
        if c[i] == c[i - 1]:
            dp[i] = 1
        else:
            dp[i] = dp[i - 1] + 1

    v = [0] * n
    v[-1] = n - 1
    for i in range(n - 2, -1, -1):
        if dp[i] + 1 == dp[i + 1]:
            v[i] = v[i + 1]
        else:
            v[i] = i

    i = 0
    while i < n:
        while i < n and v[i] == n - 1 and v[i] - i + 1 < k and c[0] != c[n - 1] and v[i] - i + 1 + v[0] + 1 >= k:
            ans += 1
            i += 1
        if i < n and v[i] - i + 1 >= k:
            ans += 1
        i += 1

    return ans

class Solution:
    def numberOfAlternatingGroups(self, c, k):
        return number_of_alternating_groups(c, k)

class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int n = colors.length;
        int[] arr = new int[n+k];
        for(int i=0;i<n;i++)arr[i] = colors[i];
        for(int i=n;i<n+k;i++)arr[i] = colors[i-n];
        n = arr.length;
        int cnt = 0;
        int[] pre = new int[n+1];
        for(int i=1;i<n;i++){
            pre[i] += pre[i-1] + Math.abs(arr[i]-arr[i-1]);
        }
        for(int i=k;i<n;i++){
            if(pre[i] - pre[i-k+1] == (k-1))cnt++;
        }
        return cnt;

    }
}

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long ans = 0;
        HashMap<Long, Long> map = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            HashMap<Long, Long> curr = new HashMap<>();
            if (nums[i] == k)ans+=1L;
            curr.put((long) nums[i], 1L);
            for (long key : map.keySet()) {  
                if ((key & nums[i]) == k) {
                    ans += map.get(key);
                }  
                curr.put(key & nums[i], curr.getOrDefault(key & nums[i], 0L) + map.get(key));
            }     
            map = curr;
        }
        return ans;
    }
}

#include <vector>
#include <string>
using namespace std;

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();

        // Create the string representation of colors
        string s;
        for (int i = 0; i < n; ++i) {
            s += to_string(colors[i]);
        }

        // Make the string circular by adding k-1 characters to the beginning and end
        string front = s.substr(0, k-1);
        // string back = s.substr(n - k+1 , k-1);

        // Construct the circular string
        s =   s + front;
        cout<<s<<endl;
        // Generate the alternating patterns
        string pattern1, pattern2;
        for (int i = 0; i < k; ++i) {
            if (i % 2 == 0) {
                pattern1 += '0';
                pattern2 += '1';
            } else {
                pattern1 += '1';
                pattern2 += '0';
            }
        }

        // Apply KMP algorithm to find occurrences
        int count = 0;

        // Find pattern1 occurrences
        count += countOccurrences(s, pattern1);

        // Find pattern2 occurrences
        count += countOccurrences(s, pattern2);

        return count;
    }

private:
    // Function to count occurrences of pattern in text using KMP algorithm
    int countOccurrences(const string& text, const string& pattern) {
        int n = text.size();
        int m = pattern.size();

        // Build KMP prefix table (lps array)
        vector<int> lps(m, 0);
        int j = 0; // length of previous longest prefix suffix
        for (int i = 1; i < m; ++i) {
            while (j > 0 && pattern[i] != pattern[j]) {
                j = lps[j - 1];
            }
            if (pattern[i] == pattern[j]) {
                lps[i] = ++j;
            } else {
                lps[i] = 0;
            }
        }

        // Perform pattern matching
        int count = 0;
        j = 0; // index for pattern[]
        for (int i = 0; i < n; ++i) {
            while (j > 0 && text[i] != pattern[j]) {
                j = lps[j - 1];
            }
            if (text[i] == pattern[j]) {
                ++j;
            }
            if (j == m) {
                ++count;
                j = lps[j - 1];
            }
        }

        return count;
    }
};

