        Map<Long, Long> prevRes = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            Map<Long, Long> currRes = new HashMap<>(); 

            if (arr[i] == k) ++count;
            currRes.put((long) arr[i], 1L);

            for (Map.Entry<Long, Long> entry : prevRes.entrySet()) {
                long val = entry.getKey(), freq = entry.getValue();
                long newAndRes = val & arr[i];

                if (newAndRes == k) count += freq;

                currRes.put(newAndRes, currRes.getOrDefault(newAndRes, 0L) + freq);
            }
            prevRes = currRes;
        }
        return count;
    }
