class Solution {
    ll subarrayANDGreaterThanK(vector<int>& nums, int k)
    {
        ll count=0;
        int left=0,curr=0;
        vector<int>bits(32,0);
        curr=~(curr);
        for(int right=0;right<nums.size();right++)
        {
            curr&=nums[right];
            for(int i=0;i<32;i++)
            {
                if(nums[right]&(1<<i))
                {
                    bits[i]++;
                }
            }
            while(left<=right&&curr<=k)
            {
                //Operation to restore AND;
                for(int i=0;i<32;i++)
                {
                    if(nums[left]&(1<<i))
                    {
                        bits[i]--;
                        // if(bits[i]==0)
                        // {
                        //     curr=(curr&~(1<<(i)));
                        // }
                    }
                    else if(bits[i]==(right-left))
                    {
                        curr=(curr|(1<<i));
                    }
                }
                left++;
            }
            if(left>right)
            {
                curr=-1;
            }
            count+=(right-left+1);
        }
        return count;
    }
    ll subarrayANDLesserThanK(vector<int>& nums, int k)
    {
        ll count=0;
        int left=0,curr=0,n=nums.size();
        vector<int>bits(32,0);
        curr=~(curr);
        for(int right=0;right<n;right++)
        {
            curr&=nums[right];
            for(int i=0;i<32;i++)
            {
                if(nums[right]&(1<<i))
                {
                    bits[i]++;
                }
            }
            while(left<=right&&curr<k)
            {
                // cout<<curr<<" "<<right<<'\n';
                //Operation to restore AND;
                for(int i=0;i<32;i++)
                {
                    if(nums[left]&(1<<i))
                    {
                        bits[i]--;
                    }
                    else if(bits[i]==(right-left))
                    {
                        curr=(curr|(1<<i));
                    }
                }
                count+=(n-right);
                left++;
            }
            if(left>right)
            {
                curr=-1;
            }
        }
        return count;
    }
public:
    ll countSubarrays(vector<int>& nums, int k) {
