class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
				long long ans=0;
				seg_tree s(n);
				s.build(0,0,n-1,nums);
				for(int i=0;i<n;i++)
				{
						int l=i;
						int h=n-1;
						int ind1=n;
						int ind2=n;
						while(l<=h)
						{
							int mid=(l+h)/2;
							if(s.query(0,0,n-1,i,mid)>(k-1)){
								l=mid+1;
							}
							else
							{
								ind1=mid;
								h=mid-1;
							}
						}
						l=i;
						h=n-1;
						while(l<=h)
						{
							int mid=(l+h)/2;
							if(s.query(0,0,n-1,i,mid)>k){
								l=mid+1;
							}
							else
							{
								ind2=mid;
								h=mid-1;
							}
						}
						ans+=1LL*(ind1-ind2);
				}
				return ans;

    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& array, int target) {
        int size = array.size();
        long long total = 0;
        unordered_map<long long, long long> previousResults;
        for (int index = 0; index < size; ++index) {
            unordered_map<long long, long long> currentResults; 
            if (array[index] == target) {
                ++total;
            }
            currentResults[array[index]] = 1;
            for (auto& [value, frequency] : previousResults) {
                long long newAndResult = value & array[index];
                if (newAndResult == target) {
                    total += frequency;
                }
                currentResults[newAndResult] += frequency;
            }

            previousResults = currentResults;
        }
        return total;
    }
};

class Solution { 
public: 
    bool cond(int a,int b){
        return a>=b;
    }
    int numberOfAlternatingGroups(vector<int>& colors, int k) { 
        int n = colors.size(); 
        int ans = 0,ctr=0;
        for(int i=0;i<n;i++)
            ctr++; 
        if (k == 1) 
            return n; 
        int al = 1,i = 1; 
        while (i < n + k - 1) { 
            int cu = i; 
            int pr = i - 1; 
            if (cond(cu, n)) 
                cu -= n;
            if (cond(pr,n) )
                pr -= n; 
            if (colors[cu] != colors[pr]) 
                ++al; 
            else 
                al = 1; 
            if (cond(al,k) )
                ++ans;
            i++; 
        } 
        return ans+ctr-ctr; 
    } 
};

