class Solution {
public:
    unordered_map<ll, ll> curr;
    unordered_map<ll, ll> oldAns;
    ll countSubarrays(vector<int>& nums, int target) {
        int n = nums.size();
        ll ans = 0;
        oldAns.clear();

        for (int i = 0; i < n; ++i) {
            curr.clear();
            if (nums[i] == target) {
                ans++;
            }
            curr[nums[i]] = 1;

            updateResults(oldAns, curr, nums[i], target, ans);

            oldAns = curr;
        }
        oldAns.clear();
        return ans;
    }

private:
    void updateResults(unordered_map<ll, ll>& prev_results,
                       unordered_map<ll, ll>& curr_results, ll num, int target,
                       ll& count) {
        for (auto& [val, freq] : prev_results) {
            ll newRes = val & num;
            if (newRes == target) {
                count += freq;
            }
            curr_results[newRes] += freq;
        }
    }
};

