class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& vec, int int_kap) {
         int n = vec.size();
       int sigma = 0, alpha = 0, beta = 1;

        while (alpha < n && beta < n + int_kap) {
            int storeBeta = beta;
            // mod
            int delta = storeBeta % n;

            // Find the end of the current alternating group
            while (storeBeta < n + int_kap - 1 && vec[delta] != vec[(delta - 1 + n) % n]) {
                // chk |@cond|
                storeBeta++;

                delta = storeBeta % n;
            }

            // Calculate the number of groups found
            sigma += max(storeBeta - alpha - int_kap + 1, 0);

            alpha = storeBeta;
            beta = alpha + 1;
        }

        return sigma;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& vec, int int_k) {
        long long epsilon = 0; 
        int n = vec.size();

        unordered_map<long long, long long> gamma;

        int alpha = 0;  // Index for it
        while (alpha < n) {

            unordered_map<long long, long long> delta;  
            if (int_k == vec[alpha]) {
                ++epsilon;  // Increment count 
            }

            delta[vec[alpha]] = 1;  // Record the occ. of the curr ele in delta map

            auto beta = gamma.begin(); 
            while (beta != gamma.end()) {
                long long val = beta->first;  
                long long freq = beta->second;  // Frequency of occurrence of the previous result
                long long newAndResult = val & vec[alpha];  // Compute the AND result with the current element

                if (newAndResult == int_k) {
                    epsilon += freq;  // If the AND result equals int_k, add the frequency to the count
                }

                delta[newAndResult] =  delta[newAndResult] + freq;  // Update the current results map with the new AND result
                ++beta;  // Move to the next entry in the previous results map
            }

            gamma = delta;  // Update previous results map with current results
            ++alpha;  
        }

        return epsilon; 
    }
};

class Solution(object):
    def numberOfAlternatingGroups(self, colors, k):
        n=len(colors)
        new_col=[0]*(n-1+k)
        for i in range(n):
            new_col[i]=colors[i]
        for i in range(k-1):
            new_col[n+i]=colors[i]
        res=0
        m=1
        p=len(new_col)
        for i in range(1,p):
            if new_col[i]!=new_col[i-1]:
                m+=1
            else:
                m=1
            if m>=k:
                res+=1
        return res

class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int n = colors.length;
        int ans = 0;
        int start = 0;
        int end = 1;
        while (end < n) {
            if (colors[end] == colors[end-1]) {
                start = end;
            }
            if (end - start + 1 >= k) ans++;
            end++;
        }
        if (colors[n-1] == colors[0]) return ans;
        if (end - start + 1 >= k) ans++;
        end = 1;
        while (end < k-1) {
            if (colors[end] == colors[end-1]) {
                return ans;
            }
            if (end + n - start + 1 >= k) ans++;
            end++;
        }
        return ans;
    }
}

class Solution(object):
    def countSubarrays(self, nums, k):
        n = len(nums)
        res = 0
        mp = dict()

        for i in range(n):
            mp2 = dict()
            if nums[i] == k:
                res += 1
            mp2[nums[i]] = 1

            for x, y in mp.items(): 
                p = x & nums[i]
                if p == k:
                    res += y
                if p in mp2:
                    mp2[p] += y
                else:
                    mp2[p] = y

            mp = mp2.copy()

