class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long ans = 0;
        int start = -1;
        int and = (1 << 31) - 1;
        int[] nearest = new int[32];
        int nearK = -1;
        Arrays.fill(nearest, -1);
        for (int end = 0; end <n; end++) {
            int currKAnd = k & nums[end];
            if (currKAnd < k) {
                start = end;
                and = (1 << 31) - 1;
                Arrays.fill(nearest, -1);
                nearK = -1;
                continue;
            }
            currKAnd = k | nums[end];
            if (currKAnd == k) {
                ans += (end - start);
                nearK = end;
            } else {
                int last = end;
                int val = nums[end] ^ k;
                for (int i=0; i<31; i++) {
                    if ((val & (1<<i)) > 0) {
                        last = Math.min(last, nearest[i]);
                    } else {
                        nearest[i] = end;
                    }
                }
                last = Math.max(nearK, last);
                if (last >= 0) ans += last - start;
                // System.out.println("__" + end + " " + last + " " + start);
            }
            // System.out.println(end + " " + ans);
        }
        return ans;
    }
}

