class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int n = colors.length;
        int[] dp = new int[n];
        dp[0] = 1;
        dp[1] = colors[0] != colors[1] ? 2 : 1;
        int count = 0;
        for(int i=2;i<n;i++){
            if(colors[i] != colors[i-1]){
                dp[i] = dp[i-1] + 1;
            }else{
                dp[i] = 1;
            }
            if(dp[i] >= k){
                count++;
            }
        }
        for(int i=0;i<k-1;i++){
            if(colors[i] != colors[(i-1+n)%n]){
                int length = dp[n-1] + i + 1;
                if(length >= k){
                    count++;
                }
            }else{
                break;
            }
        }
        return count;
    }
}

