LL fac[N], inv[N];

void getInv() {
    fac[0] = 1;
    for (int i = 1; i < N; i++) {
        fac[i] = fac[i - 1] * i % MOD;
    }
    inv[N - 1] = qmi(fac[N - 1], MOD - 2, MOD);
    for (int i = N - 1; i; i--) {
        inv[i - 1] = inv[i] * i % MOD;
    }
}

LL comb(LL n, int k) {
    if (n < k) {
        return 0;
    }
    n %= MOD;
    LL p = 1;
    for (int i = 1; i <= k; i++) {
        p = p * (n - i + 1) % MOD;
    }
    return p * inv[k] % MOD;
}

