class Solution {
public:
    static int numberOfAlternatingGroups(const vector<int>& arr, int k) {
        int n = arr.size();
        if (n < k) return 0;

        vector<int> P11(k);
        vector<int> P22(k);

        for (int i = 0; i < k; ++i) {
            P11[i] = i % 2;
            P22[i] = 1 - P11[i];
        }

        vector<int> dcolors(2 * n);
        for (int i = 0; i < 2 * n; ++i) {
            dcolors[i] = arr[i % n];
        }

        int count = counting(dcolors, P11, n, k) + counting(dcolors, P22, n, k);
        return count;
    }

private:
    static int counting(const vector<int>& str, const vector<int>& p, int olen, int k) {
        int m = p.size();
        vector<int> array = drawT(p);

        int i = 0, j = 0, count = 0;
        while (i < str.size()) {
            if (p[j] == str[i]) {
                i++;
                j++;
                if (j == m) {
                    if (i - j < olen) {
                        count++;
                    }
                    j = array[j - 1];
                }
            } else {
                if (j != 0) {
                    j = array[j - 1];
                } else {
                    i++;
                }
            }
        }
        return count;
    }
    static vector<int> drawT(const vector<int>& p) {
        int m = p.size();
        vector<int> array(m);
        int length = 0;
        array[0] = 0;
        int i = 1;
        while (i < m) {
            if (p[i] == p[length]) {
                length++;
                array[i] = length;
                i++;
            } else {
                if (length != 0) {
                    length = array[length - 1];
                } else {
                    array[i] = 0;
                    i++;
                }
            }
        }
        return array;
    }

