class Solution {
      private int[][] sparseTable;
    private int[] log;
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;

        long ans = 0;
        SparseTable(nums);
        for(int i = 0; i < n; i++){
            int low = i, high = n-1;
            int index = -1;
            while(low<=high){
                int mid =(low+high)/2;
                int cur = rangeAND(i,mid);
               if(cur >= k){
                   index = Math.max(mid,index);
                   low = mid+1;
               }else {
                   high = mid-1;
               }
            }
            int index2= n;
            low = i;
            high = n-1;
            while(low<=high){
                int mid =(low+high)/2;
                int cur = rangeAND(i,mid);
                if(cur > k){
                    low = mid+1;
                }else {
                    if(cur == k){
                        index2 = Math.min(mid,index2);
                    }
                    high = mid-1;
                }
            }
            if(index != -1 && index2 != n){
                int len = index-index2+1;
                ans+=len;
            }
        }
        return ans;
    }

    public void SparseTable(int[] arr) {
        int n = arr.length;
        int maxLog = (int) (Math.log(n) / Math.log(2)) + 1;

        // Initialize the sparse table
        sparseTable = new int[n][maxLog];
        log = new int[n + 1];

        // Precompute logs
        log[1] = 0;
        for (int i = 2; i <= n; i++) {
            log[i] = log[i / 2] + 1;
        }

        // Initialize sparse table for the intervals with length 1
        for (int i = 0; i < n; i++) {
            sparseTable[i][0] = arr[i];
        }

        // Compute values from smaller to larger intervals
        for (int j = 1; j < maxLog; j++) {
            for (int i = 0; i + (1 << j) <= n; i++) {
                sparseTable[i][j] = sparseTable[i][j - 1] & sparseTable[i + (1 << (j - 1))][j - 1];
            }
        }
    }
    public int rangeAND(int left, int right) {
        int range = right - left + 1;
        int logRange = log[range];
        return sparseTable[left][logRange] & sparseTable[right - (1 << logRange) + 1][logRange];
    }
}

