class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long ans = 0;
        vector<vector<int>> pre(n , vector<int> (32));
        for(int i = 0 ; i<32 ; i++){
            int bit = (1<<i) & nums.back();
            if(bit) pre[n-1][i] = n;
            else pre[n-1][i] = n-1;
        }
        for(int i = n-2 ; i>=0 ; i--){
            for(int j = 0 ; j<32 ;j++){
                int bit = (1<<j) & nums[i];
                if(bit) pre[i][j] = pre[i+1][j];
                else pre[i][j] = i;
            }
        }
        for(int i = 0 ; i<n ; i++){
            if(nums[i]<k) continue;
            int start = i, end = n;
            for(int j = 0 ; j<32 ; j++){
                int bit = (1<<j) & nums[i];
                int kbit = (1<<j) & k;
                if(kbit) end = min(end , pre[i][j]);
                if(!kbit) start = max(start , pre[i][j]);
            }
            ans+=max(0 ,end-start);
        }
        return ans;
    }
};

