                for(auto &it:mpp){
                    long long a=it.first;
                    long long b=it.second;
                    long long end=a&v[i];
                    if(end==k)ans+=b;
                    mp[end]+=b;
                }
                mpp=mp;
            }
            else{
                ans+=1;
                 mp[v[i]]=true;
                for(auto &it:mpp){
                    long long a=it.first;
                    long long b=it.second;
                    long long end=a&v[i];
                    if(end==k)ans+=b;
                    mp[end]+=b;
                }
                mpp=mp;
                mp.clear();
            }
            i+=1;
        }
        return ans;

    }
};

class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int n = colors.length;
        int cnt = 0;

        if (k == 1) {

            return n;
        }

        int len = 1;
        int i = 1;
        while (i < n + k - 1) {
            int cur = i;
            int prev = i - 1;


            if (cur >= n) {
                cur -= n;
            }
            if (prev >= n) {
                prev -= n;
            }

           if (colors[cur] != colors[prev]) {
                ++len;
            } else {
                len = 1;
            }

            if (len >= k) {
                ++cnt;
            }

            ++i;
        }

        return cnt;
    }
}

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long cnt = 0;

        Map<Long, Long> prev = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            Map<Long, Long> curr = new HashMap<>(); 

            if (nums[i] == k) {
               ++cnt;

            }
            curr.put((long) nums[i], 1L);

            for (Map.Entry<Long, Long> entry : prev.entrySet()) {
                long val = entry.getKey();
                long freq = entry.getValue();

                long newAnd = val & nums[i];
       if (newAnd == k) {
                    cnt += freq;
                }
                curr.put(newAnd, curr.getOrDefault(newAnd, 0L) + freq);
            }

            prev = curr;
        }

        return cnt;
    }
}

