class Solution {


public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long count = 0;
        unordered_map<int, int> prevMap;

        for (int i = 0; i < nums.size(); ++i) {
            unordered_map<int, int> currMap;
            solver(nums[i], k, currMap, prevMap, count);
            prevMap = currMap;
        }

        return count;
    }

    void solver(int num, int k, unordered_map<int, int>& currMap, unordered_map<int, int>& prevMap, long long& count) {
        if (num == k) {
            count += 1;
        }
        currMap[num] = 1;

        for (const auto& [key, value] : prevMap) {
            int newKey = key & num;
            if (newKey == k) {
                count += value;
            }
            if (currMap.find(newKey) != currMap.end()) {
                currMap[newKey] += value;
            } else {
                currMap[newKey] = value;
            }
        }
    }
};

