    public long fkn(int count[][],int i,int j,int k ){
        int ans = -1;
        int start = i;
        int end = j;
        while(start<=end){
            int mid = (start+end)/2;
            int x= c(i,mid,count);
            if(x<k){
                end=mid-1;
            }else if(x>k){
                start = mid+1;
            }
            else{
                ans =mid;
                end = mid-1;
            }
        }
            return ans;
    }
    public long fkn2(int count[][],int i,int j,int k ){
        int ans = -1;
        int start = i;
        int end = j;
        while(start<=end){
            int mid = (start+end)/2;
            int x= c(i,mid,count);
            if(x<k){
                end=mid-1;
            }else if(x>k){
                start = mid+1;
            }
            else{
                ans =mid;
                start = mid+1;
            }
        }
            return ans;

    }
    public int c(int i,int j,int arr[][]){
        int ans =0;
        for(int m = 0 ;m<=32;m++){
            if(arr[j][m]-arr[i-1][m] == j-i+1){
                ans+= (int)Math.pow(2,m);
            }
        }
        return ans;
    }
