class Solution {
public:
    int num(vector<int> &colors, int k) {
        // Extend the vector by repeating the first `k` elements at the end
        colors.insert(colors.end(), colors.begin(), colors.begin() + k);

        int n = colors.size();
        int count = 0;
        vector<int> pre(n + 1);
//         for(int i=0;i<n;i++){

//         }

        // Calculate prefix sums of absolute differences
        for (int i = 1; i < n; i++) {
            int val=abs(colors[i] - colors[i - 1]);
            pre[i] = pre[i - 1] + val;
        }

        k--; // Adjust `k` to zero-based indexing

        // Count alternating groups
        for (int i = k + 1; i < n; i++) {
            int val=pre[i-k];
            int c=pre[i];
            if (pre[i] - pre[i - k] == k) {
                count++;
            }
        }

        return count;
    }

    // Function to calculate the number of alternating groups
    // colors: vector of integers representing colors
    // k: number of consecutive elements to repeat at the end
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        return num(colors, k);
    }
};

