class Solution:
    def numberOfAlternatingGroups(self, p: List[int], b: int) -> int:
        if not p:
            return 0
        g = [] 
        l = p[0]  
        c = 1  
        s = False  
        for i in range(1, len(p)):
            if p[i] == l:
                g.append(c)
                c = 1
                s = True
            else:
                c += 1
            l = p[i]
        g.append(c)
        if len(g) == 1 and g[0] == len(p) and p[0] != p[-1] and not s:
            return len(p)
        if p[0] != p[-1] and len(g) > 1:
            last_group = g.pop()
            g[0] += last_group
        r = 0
        for group in g:
            r += max(0, group - (b - 1))
        return r

