    vector<int>seg,v1;
    void build(int id,int l,int r)
    {
        if(r-l==1)
        {
            seg[id]=v1[l];
            return;
        }
        int mid=(l+r)/2;
        build(2*id,l,mid);
        build(2*id+1,mid,r);
        seg[id]=seg[2*id]&seg[2*id+1];
    }
    int find(int x,int y,int id,int l,int r)
    {
        if(r<=x||l>y)
        {
            return -1;
        }
        if(l>=x&&r-1<=y)
        {
            return seg[id];
        }
        int mid=(l+r)/2;
        int num1=-1;
        if(!(mid<=x||l>y))num1=find(x,y,2*id,l,mid);
        int num2=-1;
        if(!(r<=x||mid>y))num2=find(x,y,2*id+1,mid,r);
        int tmp=0;
        if(num1!=-1&&num2!=-1)
        {
            tmp=num1&num2;
        }
        else if(num1==-1)
        {
            tmp=num2;
        }
        else if(num2==-1)
        {
            tmp=num1;
        }
        return tmp;
    }
    long long countSubarrays(vector<int>& nums, int k) {
