        for(int i=0;i<n;i++)
        {
            int lo=i,hi=n-1,mid,ans1=-1;
            while(lo<=hi)
            {
                mid=lo+(hi-lo)/2;
                int num=find(i,mid,1,0,n);
                if(num==k)
                {
                    ans1=mid;
                    hi=mid-1;
                }
                else if(num>k)
                {
                    lo=mid+1;
                }
                else
                {
                    hi=mid-1;
                }
            }
            lo=i,hi=n-1;
            int ans2=-1;
            while(lo<=hi)
            {
                mid=lo+(hi-lo)/2;
                int num=find(i,mid,1,0,n);
                // cout<<lo<<" "<<mid<<" "<<hi<<endl;
                if(num==k)
                {
                    ans2=max(ans2,mid);
                    // cout<<ans2<<endl;
                    lo=mid+1;
                }
                else if(num>k)
                {
                    lo=mid+1;
                }
                else
                {
                    hi=mid-1;
                }
            }
            if(ans1!=-1)
            {
                ans+=ans2-ans1+1;
            }
            // cout<<ans1<<" "<<ans2<<endl;
        }
        // cout<<seg[1]<<endl;
        // cout<<find(1,2,1,0,n)<<endl;
