class Solution
{
    public:

    int const INT_SIZE = 32;

    void bitArrayOperation(int* bitArray, int const &n, int num, int const op)
    {// add operation op = 1, sub operation op = -1;
        int i = 0;
        while ( i <= n-1 )
        {
            if ( (num & (1 << i)) ) bitArray[i] += 1*op;
            i++;
        }
    }

    int bitArrayToNum(int* bitArray, int const &n, int start, int end)
    {
        int num = 0;
        for (int i = 0; i <= n-2; i++)
        {
            if (bitArray[i] == (end - start + 1)) num += (1 << i);
        }

        return num;
    }

    void bitArrayPrint(int* bitArray, int const n = 32)
    {
        for (int i = 0; i <= n-1; i++) cout<<bitArray[i]<<" ";
        cout<<endl;
    }

    long long returnMoreThanEqualK(vector<int>& nums, int k)
    {//bit array = count of ones, more used to that
        int const n = nums.size();
        long long ans = 0;
        int bitArray[32] = {0};

        int i = 0, j = 0;
        while (j <= n-1)
        {
            bitArrayOperation(bitArray, INT_SIZE, nums[j], 1);            
            while (i <= j && bitArrayToNum(bitArray, INT_SIZE, i, j) < k)
            {
                bitArrayOperation(bitArray, INT_SIZE, nums[i], -1);                                
                i++;
            }

            ans += (j - i + 1);            
            j++;
        }

        return ans;
    }


    long long countSubarrays(vector<int>& nums, int k)
    {
        int const n = nums.size();
        long long ans = returnMoreThanEqualK(nums, k) - returnMoreThanEqualK(nums, k+1);

        return ans;
    }
};

