class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();
        if (n == 0) return 0;

        int i = 0, j = 0, count = 0;
        int ans = 0;

        while (j < n && i < n + k - 1) {
            if (colors[(i + 1) % n] != colors[i % n]) {
                count++;
                while(count > k){
                    if((colors[(j + 1) % n] != colors[j % n])){
                        count--;
                    }
                    j++;
                }

                if (count == k) {
                    // cout<<"i - "<<i<<endl;
                    ans++;
                    // count--;  // Continue looking for the next group
                }
            } else {
                if(count>=k-1) ans++;
                count = 0; // Reset the count if it's not alternating
                j = i;
                if((colors[(j + 1) % n] != colors[j % n])){
                        count++;
                    }

            }
            // cout<<i<<" i - count - "<<count<<endl;
            i++;

        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        std::unordered_map<int, int> andCount;
    long long count = 0;

    for (int num : nums) {
        std::unordered_map<int, int> newAndCount;

        if (num == k) {
            count++;
        }

        newAndCount[num] = 1;

        for (const auto& [currentAnd, freq] : andCount) {
            int newAnd = currentAnd & num;
            newAndCount[newAnd] += freq;
            if (newAnd == k) {
                count += freq;
            }
        }

        andCount = std::move(newAndCount);
    }

    return count;
    }
};

