public class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int numGroups = 0;
        int startIdx = 0;
        int endIdx = 1;
        int length = colors.length;

        while (endIdx < length + k && startIdx < length) {
            int currentEndIdx = endIdx;
            int currentEnd = currentEndIdx % length;

            while (colors[currentEnd] != colors[(currentEnd - 1 + length) % length] && currentEndIdx < length + k - 1) {
                currentEndIdx++;
                currentEnd = currentEndIdx % length;
            }

            numGroups += Math.max(currentEndIdx - startIdx - k + 1, 0);
            startIdx = currentEndIdx;
            endIdx = startIdx + 1;
        }

        return numGroups;
    }


}

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int size = nums.length;
        long total = 0;
        Map<Long, Long> previousResults = new HashMap<>();

        for (int index = 0; index < size; ++index) {
            Map<Long, Long> currentResults = new HashMap<>();
            if (nums[index] == k) {
                ++total;
            }
            currentResults.put((long) nums[index], 1L);

            for (Map.Entry<Long, Long> entry : previousResults.entrySet()) {
                long value = entry.getKey();
                long frequency = entry.getValue();
                long newAndResult = value & nums[index];
                if (newAndResult == k) {
                    total += frequency;
                }
                currentResults.put(newAndResult, currentResults.getOrDefault(newAndResult, 0L) + frequency);
            }

            previousResults = currentResults;
        }

        return total;}
}

class Solution {
