class Solution {
    public long countSubarrays(int[] nums, int k) {
        long ans = 0L;
        int n = nums.length;
        int i = 0;
        while(i < n) {
            if((nums[i]&k) == k) {
                int j = i;
                while(j < n && (nums[j]&k) == k) {
                    j ++;
                }
                int [] arr = new int [31];
                int l = i, r = i;
                while(r < j) {
                    for(int x = 0 ; x < 31 ; x++) {
                        if(((1 << x) & nums[r]) != 0) arr[x] ++;
                    }
                    int diff = r - l + 1;
                    int curr = 0;
                    for(int x = 0 ; x < 31 ; x++) {
                        if(arr[x] == diff) curr += (1 << x);
                    }
                    while(l <= r && curr == k) {
                        ans += (j - r) * 1L;
                        // System.out.println(ans + " " + l + " " + r);
                        for(int x = 0 ; x < 31 ; x++) {
                            if(((1 << x) & nums[l]) != 0) arr[x] --;
                        }
                        l ++;
                        diff = r - l + 1;
                        int temp = 0;
                        for(int x = 0 ; x < 31 ; x++) {
                            if(arr[x] == diff) temp += (1 << x);
                        }
                        curr = temp;
                    }
                    r ++;
                }
                i = j - 1;
            }
            i ++;
        }
        return ans ;
    }
}

class Solution {
public:
    int getPrefixSum(vector<int>& v, int l, int r) {
        int sum = v[r];
        if(l) {
            sum -= v[l-1];
        }
        return sum;
    }
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();
        vector<int> alterations(n, 0);
        for(int i=0; i<n; i++) {
            int nxt = (i+1)%n;
            alterations[i] += (i ? alterations[i-1] : 0) + (colors[i]!=colors[nxt]);
        }
        int ans = 0;
        for(int i = 0; i<=n-k; i++) {
            if(getPrefixSum(alterations, i, i+k-2) == k-1) {
                ans++;
            }
        }
        for(int i=n-k+1; i<n; i++) {
            int left = n-i;
            int right = k - left;
            int total = getPrefixSum(alterations, i, n-1) + ((right-2>=0) ? getPrefixSum(alterations, 0, right-2) : 0);
            if(total == k-1) {
                ans++;
            }
        }
        return ans;
    }
};

class Solution {
public:
bool isKthBitSet(int n, int k)
{
    if (n & (1 << (k - 1))) return true;
    return false;
}
    void buildTree(int ss, int se, int idx, vector<int>& v, vector<int>& st) {
        if(ss==se) {
            st[idx] = v[ss];
            return;
        }
        int m = ss+(se-ss)/2;
        buildTree(ss, m, 2*idx+1, v, st);
        buildTree(m+1, se, 2*idx+2, v, st);
        st[idx] = (st[2*idx+1] & st[2*idx+2]);
    }
    int getMax(int ss, int se, int qs, int qe, int i, vector<int>& st) {
        if(ss>qe || se<qs) {
            return INT_MAX;
        }
        if(ss>=qs && se<=qe) {
            return st[i];
        }
        int m = ss + (se-ss)/2;
        return (getMax(ss, m, qs, qe, 2*i+1, st)&getMax(m+1, se, qs, qe, 2*i+2, st));
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> st(4*n);
        buildTree(0, n-1, 0, nums, st);
        long long ans = 0;
        for(int i=0; i<n; i++) {
            int low = i, high = n-1;
            int left = -1;
            while(low<=high) {
                int mid = low + (high-low)/2;
                int val = getMax(0, n-1, i, mid, 0, st);
                bool flag = true;
                for(int i=31; i>=0; i--) {
                    int b1 = isKthBitSet(k, i+1);
                    int b2 = isKthBitSet(val, i+1);
                    if(b1 && !b2) {
                        flag = false;
                        break;
                    }
                }
                if(flag) {
                    if(val == k) {
                        left = mid;
                        high = mid-1;
                    } else {
                        low = mid+1;
                    }
                } else {
                    high = mid-1;
                }
            }
            if(left == -1) {
                continue;
            }
            low = i;
            high = n-1;
            int right;
            while(low<=high) {
                int mid = low + (high-low)/2;
                int val = getMax(0, n-1, i, mid, 0, st);
                bool flag = true;
                for(int i=31; i>=0; i--) {
                    int b1 = isKthBitSet(k, i+1);
                    int b2 = isKthBitSet(val, i+1);
                    if(b1 && !b2) {
                        flag = false;
                        break;
                    }
                }
                if(flag) {
                    if(val == k) {
                        right = mid;
                    } 
                    low = mid+1;
                } else {
                    high = mid-1;
                }
            }
            ans += right - left + 1;
        }
        return ans;
    }
};

