class SparseTable {
private:
    std::vector<std::vector<int>> table;
    std::vector<int> log;

    void build(const std::vector<int>& arr) {
        int n = arr.size();
        int max_log = std::log2(n) + 1;

        log.resize(n + 1);
        log[1] = 0;
        for (int i = 2; i <= n; ++i) {
            log[i] = log[i / 2] + 1;
        }

        table.resize(n, std::vector<int>(max_log));
        for (int i = 0; i < n; ++i) {
            table[i][0] = arr[i];
        }

        for (int j = 1; (1 << j) <= n; ++j) {
            for (int i = 0; (i + (1 << j) - 1) < n; ++i) {
                table[i][j] = table[i][j - 1] & table[i + (1 << (j - 1))][j - 1];
            }
        }
    }

public:
    SparseTable(const std::vector<int>& arr) {
        build(arr);
    }

    int query(int l, int r) {
        int j = log[r - l + 1];
        return table[l][j] & table[r - (1 << j) + 1][j];
    }
};

vector<int> get_cnt_arr(const vector<int>& arr) {
    int n = arr.size();
    vector<int> res(n);
    int i = 0;

    while (i < n) {
        int j = i;
        while (j < n && arr[j] == arr[i]) {
            j++;
        }
        int length = j - i;
        for (int k = i; k < j; k++) {
            res[k] = length - (k - i);
        }
        i = j;
    }

    return res;
}

