class Solution {
public:
    long long countSubarrays(vector<int>& nums, int K) {

        SparseTable Q(nums);

        ll N = nums.size();

        vector<int> cnt_arr = get_cnt_arr(nums);

        auto get_right = [&] (int ind) -> int {
        	int l = ind, r = N - 1;

        	int best = l;

        	while(l <= r) {
        		int mid = l + (r - l)/ 2;

        		ll cur_and = Q.query(ind, mid);

        		if(cur_and == K) {
        			best = mid;
        			r = mid - 1;
        		}
        		else if(cur_and > K){
        			l = mid + 1;
        		}
        		else r = mid - 1;
        	}

        	return best;
        };

        auto get_rightmost = [&] (int ind, int start) -> int {
            int l = start, r = N - 1, best = start;

            while(l <= r) {
                int mid = l + (r - l) / 2;
                int cur_and = Q.query(ind, mid);
                if(cur_and == K) {
                    best = max(best, mid);
                    l = mid + 1;
                }
                else {
                    r = mid - 1;
                }
            } 

            return best;
        } ;


        ll res = 0;


        for(int i = 0; i < N; i++) {
        	int right = get_right(i);


        	if(Q.query(i, right) == K) {
				// res += cnt_arr[right];       
                int right_most_ind = get_rightmost(i, right);

                res += (right_most_ind - right + 1);
        	}
        }

        return res;
    }
};

