class Solution {
public:
    long long int calc(vector<int>&v, int k){
        int n = v.size();
        long long int ans = 0;

        vector<vector<int>> dp(n+1, vector<int> (32,0));
        for(int j=1; j<=n; j++){
            for(int i=0; i<32; i++){
                dp[j][i] += dp[j-1][i];
            }
            for(int i=0; i<32; i++){
                if(v[j-1] & (1LL<<i)) dp[j][i]++;
            }
        }

        // for(auto x: dp){
        //     for(auto y:x) cout<<y<<" "; cout<<'\n';
        // }

        int j = 1;
        for(int i=1; i<=n; i++){
            while(j<=n && j<=i){
                int temp=0;
                for(int a=0; a<32; a++){
                    if(dp[i][a]-dp[j-1][a]==i-j+1) temp|=(1LL<<a);
                }
                if(temp==k){
                    ans += n-i+1;
                    j++;
                }
                else break;
            }
        }
        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        vector<int> temp;
        int n = nums.size();
        long long ans = 0;
        for(int i=0; i<n; ){
            while(i<n && ((nums[i]&k) == k)){
                temp.push_back(nums[i]);
                i++;
            }
            if(temp.size()){ 
                ans += calc(temp, k);
                temp.clear();
            }
            else i++;
        }
        return ans;
    }
};

