class Solution {
public:
    long long countSubarrays(vector<int>& numbers, int target) {
        int length = numbers.size();
        long long totalCount = 0;
        unordered_map<long long, long long> previousResults;

        for (int i = 0; i < length; ++i) {
            unordered_map<long long, long long> currentResults;

            if (numbers[i] == target) {
                ++totalCount;
            }

            currentResults[numbers[i]] = 1;

            for (auto& [value, frequency] : previousResults) {
                long long andResult = value & numbers[i];

                if (andResult == target) {
                    totalCount += frequency;
                }

                currentResults[andResult] += frequency;
            }

            previousResults = currentResults;
        }

        return totalCount;
    }
};

class Solution {
    func numberOfAlternatingGroups(_ colors: [Int], _ k: Int) -> Int {
        var numGroups = 1
        var alt = true
        var lastNonAltIndex = -1
        let len = colors.count

        var i = 0
        while i < (k - 1) {
            if colors[i] == colors[i + 1] {
                alt = false
                numGroups = 0
                lastNonAltIndex = i
                i += 1
                continue
            }
            i += 1
        }

        var j = 1
        while j < len {
            if alt && colors[(k - 2 + j) % len] != colors[(k + j - 1) % len] {
                numGroups += 1
            } else if alt && colors[(k - 2 + j) % len] == colors[(k + j - 1) % len] {
                alt = false
                lastNonAltIndex = k + j - 2
            } else if !alt && j <= lastNonAltIndex {
                if colors[(k - 2 + j) % len] == colors[(k + j - 1) % len] {
                    lastNonAltIndex = k + j - 2
                }
                j += 1
                continue
            } else if !alt && j > lastNonAltIndex {
                if colors[(k - 2 + j) % len] != colors[(k + j - 1) % len] {
                    numGroups += 1
                    alt = true
                } else {
                    lastNonAltIndex = k - 2 + j
                    alt = false
                }
            }
            j += 1
        }
        return numGroups
    }
}

class Solution {
    func countSubarrays(_ nums: [Int], _ k: Int) -> Int {
        let size = nums.count
        var total: Int64 = 0
        var previousResults: [Int64: Int64] = [:]

        var index = 0
        while index < size {
            var currentResults: [Int64: Int64] = [:]

            if nums[index] == k {
                total += 1
            }
            currentResults[Int64(nums[index])] = 1

            for (value, frequency) in previousResults {
                let newAndResult = value & Int64(nums[index])
                if newAndResult == k {
                    total += frequency
                }
                currentResults[newAndResult, default: 0] += frequency
            }

            previousResults = currentResults
            index += 1
        }
        return Int(total)
    }
}

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();

        vector<int> vec(n + k - 1);
        for(int i = 0; i < vec.size(); i++)
        {
            vec[i] = colors[i % n];
        }

        int ct = 0, res = 0;
        for(int i = 0; i < vec.size(); i++)
        {
            ct++;
            if(ct >= k)
            {
                res++;
            }
            if((i + 1) < vec.size() && vec[i] == vec[i + 1])
            {
                ct = 0;
            }
        }
        return res;
    }
};

class Solution {
