class Solution {
   public int numberOfAlternatingGroups(int[] colors, int k) {
        int size = 1;
        int count = 0;
        int n = colors.length;

        for (int i = 1; i < n + k - 1; i++) {
            if (colors[i % n] != colors[(i - 1) % n]) {
                size++;
                if (size == k) {
                    count++;
                    size--;
                }
            } else {
                size = 1;
            }
        }

        return count;
    }

}

class Solution {
    public long countSubarrays(int[] nums, int target) {
        int n = nums.length;
        long count = 0;

        Map<Long, Long> previousResults = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            Map<Long, Long> currentResults = new HashMap<>();

            if (nums[i] == target) {
                ++count;
            }
            currentResults.put((long) nums[i], 1L);

            for (Map.Entry<Long, Long> entry : previousResults.entrySet()) {
                long value = entry.getKey();
                long frequency = entry.getValue();

                long newAndResult = value & nums[i];
                if (newAndResult == target) {
                    count += frequency;
                }

                currentResults.put(newAndResult, currentResults.getOrDefault(newAndResult, 0L) + frequency);
            }

            previousResults = currentResults;
        }

        return count;

    }
}

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& col, int k) {

        int num=0;
        int i=0,j=1;
        int n=col.size();
        while(j<n+k && i<n){
            int temp =j;
            int te=temp%n;
            while(col[te]!=col[(te-1+n)%n]&&temp<(n+k-1)){
                temp++;
                te=temp%n;
            }
            num+=std::max(temp-i-k+1,0);
            i=temp;
            j=i+1;
}
        return num;
    }
};

