const int N=1e5+1;
int  Seg_Tree[4*N];

void build(vector<int> &arr,int x,int l,int r){
    if(r-l==1){
        Seg_Tree[x]=arr[l];
        return ;
    }
    int mid=l+(r-l)/2;
    build(arr,2*x+1,l,mid);
    build(arr,2*x+2,mid,r);
    Seg_Tree[x]=(Seg_Tree[2*x+1]&Seg_Tree[2*x+2]);
}
int query(int x,int a,int b,int l,int r){

    if(a>=r || b<=l){
        return -1;
    }
    else if(a<=l && b>=r){
        return Seg_Tree[x];
    }
    int mid=l+(r-l)/2;
    auto left=query(2*x+1,a,b,l,mid);
    auto right=query(2*x+2,a,b,mid,r);
    return (left&right);
}
class Solution {
public:
    long long countSubarrays(vector<int>& arr, int k) {
        long long res=0;
        int n=arr.size();
        build(arr,0,0,n);
        for(int i=0;i<n;i++){
            // if((arr[i]&k)!=k)continue ;
            int l=i,h=n-1,m;
            while(l<=h){
                m=(l+h)/2;
                int x=query(0,i,m+1,0,n);
                // cout<<i<<"\t"<<m<<'\t'<<x<<'\n';
                if(x>k){
                    l=m+1;
                }
                else{
                    h=m-1;
                }
            }

            int L=l;
            h=n-1;
            while(l<=h){
                m=(l+h)/2;
                int x=query(0,i,m+1,0,n);
                if(x>=k){
                    l=m+1;
                }
                else{
                    h=m-1;
                }
            }
            // cout<<i<<'\t'<<l<<'\t'<<L<<'\n';
            res+=(l-L);
        }
        return res;



    }
};
