class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& v, int k) {
        int n=v.size();
        for(int i=0; i<n; i++)v.push_back(v[i]);
        int i=0, j=0, res=0;
        // for(int i=0; i<v.size(); i++){
        //     cout << v[i] << " ";
        // }
        // cout << endl;
        while(i<n+k-1){
            int j=i+1;
            while(j<n+k-1 && v[j]!=v[j-1])j++;
            int len=j-i;
            // cout << i << " " << j << " " << len << endl;
            int cur=max(0, len-k+1);
            res+=cur;
            i=j;
        }
        return res;
    }
};

class Solution {
public:
    typedef long long ll; 

struct item {
    ll ac;
};

struct sparseTable {
    ll sze;
    ll mxlog;
    vector<ll> logval;
    vector<vector<item>> table;

    item merge(item a, item b) { // min, max, gcd
        return {a.ac&b.ac};
    }

    item single(ll v) {
        return {v};
    }

    void build(vector<ll> &a) {
        sze = a.size();
        mxlog = log2(sze);
        table.resize(sze + 1);
        logval.resize(sze + 1);

        logval[1] = 0;
        for (ll i = 2; i <= sze; ++i) {
            logval[i] = logval[i / 2] + 1;
        }

        for (ll i = 0; i < sze; ++i) {
            table[i].resize(mxlog + 1);
            fill(table[i].begin(), table[i].end(), item());
        }

        for (ll i = 0; i < sze; i++) {
            table[i][0] = single(a[i]);
        }
        for (ll i = 1; i <= mxlog; i++) {
            for (ll j = 0; (j + (1 << i)) <= sze; j++) {
                table[j][i] = merge(table[j][i - 1], table[j + (1 << (i - 1))][i - 1]);
            }
        }
    }

    item query(ll l, ll r) {
        ll j = logval[r - l + 1];
        item ans = item();
        ans = merge(table[l][j], table[r - (1 << j) + 1][j]); // O(1)
        return ans;
    }
};



    ll cnt(vector<int> &v, int k, int l, int r, sparseTable &st){

        ll res=-1, idx=l;
        while(l<=r){
            ll mid=l+(r-l)/2;
            ll val=st.query(idx, mid).ac;
            // cout << l << " " << mid << " " << r << " " << val << endl;
            if(val>=k){
                res=max(res, mid);
                l=mid+1;
            }else r=mid-1;
        }
        // cout << res << endl;
        if(res==-1)return 0;
        return res-idx+1;
    }


    long long countSubarrays(vector<int>& nums, int k) {
        vector<ll> v;
        for(auto x: nums)v.push_back(x);
        sparseTable st;
        st.build(v);
        ll res=0, n=nums.size();
        for(int i=0; i<n; i++){
            ll r = cnt(nums, k, i, n-1, st), l = cnt(nums, k+1, i, n-1, st);
            // cout << l << " " << r << " " << i << endl;
            ll cur=r-l;
            res+=cur;
        }
        return res;
    }
};

class Solution {
