        int ans = 0;
        vector<int> v;
        for(int i = 0;i<n;i++){
            v.push_back(colors[i]);
        }
        for(int i = 0;i<k-1;i++){
            v.push_back(colors[i]);
        }
        int sz = 1;
        for(int i = 1;i<v.size();i++){
            if(v[i] != v[i-1]){
                sz++;
            }
            else{
                ans += max(0,sz - k + 1);
                sz = 1;
            }
        }
        ans += max(0,sz - k + 1);
        return ans;
    }
};

class Solution {
public:
    class SegTree {
        vector<int> seg;

    public:
        SegTree(int n) { seg.resize(4 * n + 1, INT_MAX); }
        void build(int ind, int low, int high, vector<int>& arr) {
            if (low == high) {
                seg[ind] = arr[low];
                return;
            }
            int mid = (low + high) / 2;
            build(2 * ind + 1, low, mid, arr);
            build(2 * ind + 2, mid + 1, high, arr);
            seg[ind] = seg[2 * ind + 1] & seg[2 * ind + 2];
        }
        int query(int ind, int low, int high, int l, int r) {
            // no overlap
            // l r low high || low high l r
            if (l > high || r < low) {
                return INT_MAX;
            }
            // complete overlap
            // l low high r
            if (l <= low && r >= high) {
                return seg[ind];
            }
            // partial overlap
            int mid = (low + high) / 2;
            int left = query(2 * ind + 1, low, mid, l, r);
            int right = query(2 * ind + 2, mid + 1, high, l, r);
            return left & right;
        }
        void update(int ind, int low, int high, int i, int val,
                    vector<int>& arr) {
            if (low == high) {
                seg[ind] = val;
                arr[i] = val;
                return;
            }
            int mid = (low + high) / 2;
            if (i <= mid) {
                update(2 * ind + 1, low, mid, i, val, arr);
            } else {
                update(2 * ind + 2, mid + 1, high, i, val, arr);
            }
            seg[ind] = seg[2 * ind + 1] & seg[2 * ind + 2];
        }
    };
    long long countSubarrays(vector<int>& nums, int k) {
        SegTree st(nums.size());
        st.build(0, 0, nums.size() - 1, nums);
        int n = nums.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int lo = i - 1, hi = n - 1;
            while (hi - lo > 1) {
                int mid = (lo + hi) / 2;
                int val = st.query(0, 0, n - 1, i, mid);
                if (val > k) {
                    lo = mid;
                } else {
                    hi = mid;
                }
            }
            if (st.query(0, 0, n - 1, i, hi) == k) {
                int lo1 = hi - 1, hi1 = n;
                while (hi1 - lo1 > 1) {
                    int mid = (lo1 + hi1) / 2;
                    int val = st.query(0, 0, n - 1, i, mid);
                    if (val >= k) {
                        lo1 = mid;
                    } else {
                        hi1 = mid;
                    }
                }
                //cout << hi1 << " " << lo1 << " " << hi << endl;
                if (st.query(0, 0, n - 1, i, lo1) == k) {
                    ans += max(0, min(n - 1, lo1) - max(0,hi) + 1);
                } else {
                    ans += 1;
                }
            }
        }
        return ans;
    }
};

class Solution {
 public int numberOfAlternatingGroups(int[] colors, int k) {
        int ans = 0;
        int n = colors.length;

        List<Integer> extendedColors = new ArrayList<>();
        for (int color : colors) {
            extendedColors.add(color);
        }
        for (int i = 0; i < k - 1; i++) {
            extendedColors.add(colors[i]);
        }

        int count = 0;
        int prev = (extendedColors.get(0) == 0 ? 1 : 0);

        // Iterate through the extended array
        for (int i = 0; i < extendedColors.size(); i++) {
            if (prev == extendedColors.get(i)) {
                count = 1;
            } else {
                count++;
            }
            prev = extendedColors.get(i);
            if (count >= k) {
                ans++;
            }
        }

        return ans;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public long countSubarrays(int[] arr, int target) {
        int n = arr.length;
        long total = 0;
        Map<Long, Long> prev = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            Map<Long, Long> curr = new HashMap<>();

            if (arr[i] == target) {
                ++total;
            }

            curr.put((long) arr[i], 1L);

            for (Map.Entry<Long, Long> entry : prev.entrySet()) {
                long andResult = entry.getKey() & arr[i];

                if (andResult == target) {
                    total += entry.getValue();
                }

                curr.put(andResult, curr.getOrDefault(andResult, 0L) + entry.getValue());
            }

            prev = curr;
        }

        return total;
    }
}

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& arr, int k) {
         int num_found = 0;
        int i = 0, j = 1;
        int n = arr.size();

        while (j < n + k && i < n) {
            int temp_j = j;
            int temp_end = temp_j % n;

            while (arr[temp_end] != arr[(temp_end - 1 + n) % n] && temp_j < (n + k - 1)) {
                temp_j++;
                temp_end = temp_j % n;
            }

            num_found += std::max(temp_j - i - k + 1, 0);
            i = temp_j;
            j = i + 1;
        }

        return num_found;
    }
};

