class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int N = colors.length;
        int count = 0;
        if (k == 1) {
            return N;
        }
        int alternatingLength = 1;
        int i = 1;
        while (i < N + k - 1) {
            int current = i;
            int previous = i - 1;
            if (current >= N) {
                current -= N;
            }
            if (previous >= N) {
                previous -= N;
            }

            if (colors[current] != colors[previous]) {
                ++alternatingLength;
            } else {
                alternatingLength = 1;
            }
            if (alternatingLength >= k) {
                ++count;
            }
            ++i;
        }
        return count;
    }
}

