class Solution {
   public:
    int numberOfAlternatingGroups(vector<int>& a, int k) {
        vector<vector<int>> runs;
        int n = a.size();
        vector<int> curr;
        for (int i = 0; i < n; i++) {
            if (curr.empty()) {
                curr.push_back(a[i]);
            } else {
                if (curr.back() != a[i]) {
                    curr.push_back(a[i]);
                } else {
                    runs.push_back(curr);
                    curr.clear();
                    curr.push_back(a[i]);
                }
            }
        }
        runs.push_back(curr);
        int ans = 0;
        if (runs.size() == 1) {
            if (n % 2 == 1) {
                return n - k + 1;
            } else {
                return n;
            }
        } else {
            if (a.back() != a.front()) {
                int len = runs.size();
                int first = runs.front().size() + runs.back().size();
                ans += max(first - k + 1, 0);
                for (int i = 1; i < len - 1; i++) {
                    ans += max((int)runs[i].size() - k + 1, 0);
                }
            } else {
                for (auto& v : runs) {
                    ans += max((int)v.size() - k + 1, 0);
                }
            }
        }
        return ans;
    }
};
