class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int ans{0};
        const int n = colors.size();
        vector<int> dp(n, 0);
        for (int i = 0; i < n; i++) {
            if (i > 1 && dp[i-1] == 1) {
                int n1 = (i + k - 2) % n;
                int n2 = (i + k - 1) % n;
                if (colors[n1] != colors[n2]) {
                    dp[i] = 1;
                    ans++;
                } else {
                    if (i + k - 2 >= n) {
                        break;
                    }
                    i = n1;
                }
                cout << "1 i=" << i << endl;
                continue;
            }
            int next{0};
            if (check(colors, k, i, next)) {
                dp[i] = 1;
                ans++;
            } else {
                if (next >= n) {
                    break;
                }
                i = next;
            }
        }
        return ans;
    }
    bool check(vector<int>& colors, int k, int idx, int& next) {
        int n = colors.size();
        for (int i = 0; i < k - 1; i++) {
            int n1 = (idx + i) % n;
            int n2 = (idx + i + 1) % n;
            if (colors[n1] == colors[n2]) {
                next = idx + i;
                return false;
            }
        }
        return true;
    }
};

