class Solution {
public:
    int prefix_count[32][100001];

        void findPrefixCount(vector<int> arr, int n)
        {
            for (int i = 0; i < 32; i++) {
                prefix_count[i][0] = ((arr[0] >> i) & 1);
                for (int j = 1; j < n; j++) {
                    prefix_count[i][j] = ((arr[j] >> i) & 1);
                    prefix_count[i][j] += prefix_count[i][j - 1];
                }
            }
        }

        // Function to answer query
        int rangeAnd(int l, int r)
        {
            int ans = 0;
            for (int i = 0; i < 32; i++) {
                int x;
                if (l == 0){
                    x = prefix_count[i][r];
                }
                else{
                    x = prefix_count[i][r]- prefix_count[i][l - 1];
                }
                if (x == r - l + 1){
                    ans = (ans | (1 << i));
                }
            }

            return ans;
        }
    long long countSubarrays(vector<int>& nums, int k){
        int n=nums.size();
        findPrefixCount(nums,n);
        long long ans=0;
        for(int i=0;i<n;i++){
            if((nums[i]&k)!=k){
                continue;
            }
            int start=0,end=0;
            int low=i;
            int high=n-1;
            while(high-low>1){
                int mid=(high+low)/2;
                if(rangeAnd(i,mid)<=k){
                    high=mid;
                }
                else{
                    low=mid;
                }
            }
            // cout<<i<<" ";
            if(rangeAnd(i,low)==k){
                start=low;
            }
            else if(rangeAnd(i,high)==k){
                start=high;
            }
            else{
                // cout<<i<<endl;
                continue;
            }
            low=i;
            high=n-1;
            while(high-low>1){
                int mid=(high+low)/2;
                if(rangeAnd(i,mid)<k){
                    high=mid;
                }
                else{
                    low=mid;
                }
            }
            if(rangeAnd(i,high)==k){
                end=high;
            }
            else{
                end=low;
            }
            // cout<<i<<" "<<end<<" "<<start<<endl;
            ans+=(end-start+1);
        }
        // cout<<endl;
        return ans;
    }
};

