class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long total_count = 0;

        unordered_map<long long, long long> previous_results;

        for (int i = 0; i < n; ++i) {
            unordered_map<long long, long long> current_results; 

            if (nums[i] == k) {
                ++total_count;
            }
            current_results[nums[i]] = 1;

            for (auto& [value, frequency] : previous_results) {
                long long new_and_result = value & nums[i];
                if (new_and_result == k) {
                    total_count += frequency;
                }
                current_results[new_and_result] += frequency;
            }

            previous_results = current_results;
        }

        return total_count;
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();
        int ans = 0;
        int count = 0;
        for (int i = 1; i < k; i++) {
            if (colors[i] != colors[i - 1]) {
                count++;
            }
        }
        if (count == (k - 1)) {
            ans++;
        }
        //cout<<ans<<endl;
        for (int i = 1; i < n; i++) {
            if (colors[i - 1] != colors[i]) {
                count--;
            }
            if (colors[(i + k - 1) % n] != colors[(i + k - 2) % n]) {
                count++;
            }
            if (count == (k - 1)) {
                ans++;
            }
        }

        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        unordered_map<int, long long> dp;
        for (int i : nums) {
            unordered_map<int, long long> curr;
            if (i == k) ans++;
            curr[i] = 1;
            for (auto& [key, value] : dp) {
                if ((key & i) == k) {
                    ans += value;
                }
                curr[(key & i)] += value;
            }
            dp = curr;

        }
        return ans;
    }
};

