class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        SegmentTree segTree(nums);

        long long ans = 0;

        for(int i=0; i<n; i++){


            // B.s to find first index
            int l = i, r = n-1;
            int firstInd = -1;

            while(l<=r){
                int mid = (l+r)>>1;
                int res = segTree.query(i, mid);


                if(res > k) l = mid + 1;
                else if(res < k) r = mid - 1;
                else {
                    firstInd = mid;
                    r = mid - 1;
                }
            }

//             if(firstInd == -1) continue;


            // B.s to find last index
            l = i, r = n-1;
            int lastInd = -1;

            while(l<=r){
                int mid = (l+r)>>1;
                int res = segTree.query(i, mid);


                if(res > k) l = mid + 1;
                else if(res < k) r = mid - 1;
                else {
                    lastInd = mid;
                    l = mid + 1;
                }
            }

            // cout<<"i, last, first: "<< i<<" "<<lastInd<<' '<<firstInd<<endl;
            if(firstInd != -1 && lastInd != -1) 
                ans += (lastInd - firstInd + 1);
            else if(lastInd != -1) ans += lastInd - i + 1;
        }

        return ans;
    }
