class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();
        int count = 0;
        vector<int> groupLengths(n);
        map<int,int>mp;
        groupLengths[0] = 1;
        for (int i = 1; i < n; ++i) {
            if (colors[i] == colors[i - 1]) {
                groupLengths[i] = 1;
                mp[colors[i]]++;
            } else {
                groupLengths[i] = groupLengths[i - 1] + 1;
            }
        }

        vector<int> groupEnd(n);
        groupEnd[n - 1] = n - 1;
        for (int i = n - 2; i >= 0; --i) {
            if (groupLengths[i] + 1 == groupLengths[i + 1]) {
                groupEnd[i] = groupEnd[i + 1];
            } else {
                groupEnd[i] = i;
                 mp[colors[i]]++;
            }
        }
        int index = 0;
        while (index < n) {
            while (index < n && groupEnd[index] == n - 1 &&  colors[0] != colors[n - 1] && groupEnd[index] - index + 1 < k && groupEnd[index] - index + 1 + groupEnd[0] + 1 >= k) {
                count++;
                index++;
            }
            if (index < n && groupEnd[index] - index + 1 >= k) {
                count++;
            }
            index++;
        }
        int k1=mp[index];
        if(k1<=k)mp[k1]--;
        return count;
    }
};

