class SegmentTree {
public:
    SegmentTree(const vector<int>& data) {
        n = data.size();
        tree.resize(2 * n);
        build(data);
    }

    void update(int pos, int value) {
        pos += n;
        tree[pos] = value;
        while (pos > 1) {
            pos /= 2;
            tree[pos] = tree[2 * pos] & tree[2 * pos + 1];
        }
    }

    int range_and(int left, int right) {
        left += n;
        right += n + 1;
        int result = INT_MAX;
        while (left < right) {
            if (left % 2 == 1) {
                result &= tree[left];
                left++;
            }
            if (right % 2 == 1) {
                right--;
                result &= tree[right];
            }
            left /= 2;
            right /= 2;
        }
        return result;
    }

private:
    int n;
    vector<int> tree;

    void build(const vector<int>& data) {
        for (int i = 0; i < n; ++i) {
            tree[n + i] = data[i];
        }
        for (int i = n - 1; i > 0; --i) {
            tree[i] = tree[2 * i] & tree[2 * i + 1];
        }
    }
};
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) 
    {
        SegmentTree segtree = SegmentTree(nums);
        ll res = 0;

        ll N = nums.size();

        forn(i,N)
        {
            ll lo = i,hi = N;
            ll MX = -1;
            while (lo < hi) {
                ll mid = lo + (hi - lo) / 2; 
                ll val = segtree.range_and(i, mid);

                if (val < k) {
                    hi = mid; 
                } else if (val == k) {
                    MX = max(MX, mid);
                    lo = mid + 1; 
                } else { // val > k
                    lo = mid + 1; 
                }
            }

            if(MX == -1)
                continue;
            lo = i;
            hi = MX;
            ll MN = MX;

            while (lo < hi) 
            {
                ll mid = lo + (hi - lo) / 2; 
                ll val = segtree.range_and(i, mid);

                if (val < k) {
                    hi = mid; 
                } else if (val == k) {
                    MN = min(MN, mid);
                    hi = mid; 
                } else { // val > k
                    lo = mid + 1; 
                }
            }
            res += (MX-MN + 1);


        }
        return res;


    }
};

