        Map<Integer,Map<Integer,Long>> dp = new HashMap<>();
        for(int i=index ; i<nums.length ; i++){
            dp.put(i, new HashMap<>());
        }
        long ans = 0;
        for(int i=index ; i<nums.length ; i++){
            ans += countSubarraysHelper(i, nums,1073741823, k, dp);
        }
        return ans;
    }
    private long countSubarraysHelper(int index, int[] nums, int and, int k, Map<Integer,Map<Integer,Long>> dp){
        if(index==nums.length){
            return and == k ? 1 : 0;
        }
        if(dp.get(index).containsKey(and)){
            return dp.get(index).get(and);
        }
        long ans = 0;
        ans += countSubarraysHelper(index+1, nums, and&nums[index], k, dp);
        ans += and == k ? 1 : 0;
        dp.get(index).put(and, ans);
        return ans;
    }
}

