class Solution {
    public long countSubarrays(int[] nums, int k) {
        List<Integer> list = new ArrayList();
        long result = 0;
        for (int num : nums) {
        	if ((num & k) < k) {
        		if (list.size() > 0) {
        			result += findK(list, k);
        			list.clear();
        		}
        	} else {
        		list.add(num);
        	}
        }
        if (list.size() > 0)
			result += findK(list, k);
        return result;
    }

	private static long findK(List<Integer> list, int k) {
		int[] count = new int[32];
		for (int i = 0; i < 32; i++) {
		    count[i] = ((k & (1 << i)) != 0) ? -1 : 0;
		}
		int result = Integer.MAX_VALUE;
		int index = 0;
		int n = list.size();
		while (result > k && index < n) {
			int now = list.get(index++);
			result = result & now;
			for (int j = 0; j < 32; j++) {
				if (count[j] == -1)
					continue;
			    count[j] += ((now & (1 << j)) != 0) ? 0 : 1;
			}
		}
		if (result > k)
			return 0;
		long val = n - index + 1;
		for (int i = 1; i < n; i++) {
			for (int j = 0; j < 32; j++) {
				if (count[j] == -1)
					continue;
			    count[j] -= ((list.get(i - 1) & (1 << j)) != 0) ? 0 : 1;
			}
			boolean check = pass(count);
			while (!check && index < n) {
				int now = list.get(index++);
				for (int j = 0; j < 32; j++) {
				if (count[j] == -1)
					continue;
				    count[j] += ((now & (1 << j)) != 0) ? 0 : 1;
				}
				check = pass(count);
			}
			if (!check)
				return val;
			val += n - index + 1;
		}
		return val;
    }

	private static boolean pass(int[] count) {
		for (int i = 0; i < 32; i++) {
			if (count[i] == 0)
				return false;
		}
		return true;
	}
}

