class Solution {
    public long countSubarrays(int[] nums, int k) {
        // System.out.println();
        long count = 0;
        List<int[]> onesValid = enforceOnes(nums, k, List.of(new int[] { 0, nums.length }), 0);
        for (int[] interval : onesValid) {
            // System.out.println(Arrays.toString(interval));
            int L = interval[0]; int R = interval[1];
            int[][] prefix = new int[32][R - L + 1];
            for (int b = 0; b < 32; b++) {
                for (int r = L + 1; r <= R; r++) {
                    prefix[b][r - L] = prefix[b][r - L - 1] + (1 - ((nums[r-1] >> b) & 1));
                }
            }
            search: for (int l = L; l <= R; l++) {
                for (int b = 0; b < 32; b++) {
                    if (((k >> b) & 1) == 1) continue;
                    if (prefix[b][R - L] - prefix[b][l - L] == 0) {
                        continue search;
                    }
                }
                int a = l; int b = R;
                while (a + 1 != b) {
                    int m = a + (b - a) / 2;
                    boolean Mvalid = true;
                    for (int b_ = 0; b_ < 32; b_++) {
                        if (((k >> b_) & 1) == 1) continue;
                        if (prefix[b_][m - L] - prefix[b_][l - L] == 0) {
                            Mvalid = false;
                            break;
                        }
                    }
                    if (Mvalid) {
                        b = m;
                    } else {
                        a = m;
                    }
                }
                count += R - b + 1;
            }
        }
        return count;
    }

    public List<int[]> enforceOnes(int[] nums, int k, List<int[]> valid, int b) {
        if (b == 32) return valid;
        if (((k >> b) & 1) == 0) return enforceOnes(nums, k, valid, b + 1);
        List<int[]> adjusted = new LinkedList<>();
        for (int[] interval : valid) {
            int L = interval[0]; int R = interval[1]; int l = L;
            while (l < R) {
                while (l < R && ((nums[l] >> b) & 1) == 0) l++;
                if (l == R) break;
                int r = l;
                while (r < R && ((nums[r] >> b) & 1) == 1) r++;
                adjusted.add(new int[] { l, r });
                l = r;
            }
        }
        return enforceOnes(nums, k, adjusted, b + 1);
    }
}

class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int[] copy = new int[colors.length + k - 1];
        System.arraycopy(colors, 0, copy, 0, colors.length);
        System.arraycopy(colors, 0, copy, colors.length, copy.length - colors.length);
        int[] prefix = new int[copy.length];
        for (int i = 1; i < copy.length; i++) {
            prefix[i] = prefix[i-1];
            if (copy[i] != copy[i-1]) prefix[i]++;
        }
        int count = 0;
        for (int i = 0; i < colors.length; i++) {
            if (prefix[i+k-1] - prefix[i] == k - 1) count++;
        }
        return count;
    }
}

class Solution {
    public int numberOfAlternatingGroups(int[] petals, int bouquet) {
        // Initialize variables
        List<Integer> groups = new ArrayList<>();
        int lastPetals = petals[0];
        int currentGroup = 1;
        boolean isSame = false;

        for (int i = 1; i < petals.length; i++) {
            if (petals[i] == lastPetals) {
                groups.add(currentGroup);
                currentGroup = 1;
                isSame = true;
            } else {
                currentGroup++;
            }
            lastPetals = petals[i];
        }
        groups.add(currentGroup);

        if (groups.size() == 1 && groups.get(0) == petals.length && petals[0] != petals[petals.length - 1] && !isSame) {
            return petals.length;
        }

        if (petals[0] != petals[petals.length - 1] && groups.size() > 1) {
            int lastGroup = groups.remove(groups.size() - 1);
            groups.set(0, groups.get(0) + lastGroup);
        }

        long res = 0;
        for (int group : groups) {
            res += Math.max(0, group - (bouquet - 1));
        }

        return (int) res;
    }
}

