class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int numberOfGroupsFound = 0,startIndex = 0;
        int endIndex = 1;
        int arrayLength = colors.length;

        while (endIndex < arrayLength + k && startIndex < arrayLength) {
            int tempEndIndex = endIndex,tempEnd = tempEndIndex % arrayLength;
            while (colors[tempEnd] != colors[(tempEnd - 1 + arrayLength) % arrayLength] && tempEndIndex < arrayLength + k - 1) {
                tempEndIndex++;
                tempEnd = tempEndIndex % arrayLength;
            }
            numberOfGroupsFound += Math.max(tempEndIndex - startIndex - k + 1, 0);
            startIndex = tempEndIndex;
            endIndex = startIndex + 1;
        }

        return numberOfGroupsFound;
    }
