class SegmentTree {
    vector<int> tree;
    int n;
public:
    SegmentTree(const vector<int>& arr): n(arr.size()), tree(arr.size() << 1) {
        copy(arr.begin(), arr.end(), tree.begin() + n);
        for (int i = n - 1; i > 0; --i) {
            tree[i] = tree[i<<1] & tree[i<<1|1];
        }
    }

    // Important: sum of range [l, r) (exclusive)
    int bitwiseAnd(int l, int r) {
        int s = INT_MAX;
        for (l +=n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {
                s &= tree[l++];
            }
            if (r & 1) {
                s &= tree[--r];
            }
        }
        return s;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        SegmentTree st(nums);
        int i = 0;
        const int n = nums.size();
        int bitAnd = INT_MAX;
        long long ans = 0, count = 0;
        for (int j = 0; j < n; ++j) {
            bitAnd &= nums[j];
            // cout << "and: "<<bitAnd<<endl;

            if (bitAnd < k) {
                ++i;
                count = 0;
                while (i <= j) {
                    const int sub = st.bitwiseAnd(i, j + 1);
                    if (sub < k) {
                        ++i;
                    } else {
                        bitAnd = sub;
                        break;
                    }
                }
                if (i == j + 1) {
                    bitAnd = INT_MAX;
                }
                // cout << "and after: "<<bitAnd<<endl;
            }

            if (bitAnd == k) {
                // cout << "count: "<<count<<", i: "<<i<<endl;
                ans += count + 1;
                ++i;
                while (i <= j && st.bitwiseAnd(i, j + 1) == k) {
                    ++i;
                    ++ans;
                    ++count;
                }
                --i;
            }

            // cout <<ans <<endl;
        }
        return ans;
    }
};

