class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        # imagine a matrix: columns are numbers, rows are binary digits
        # iterate through subarray beginnings: left from 0 to n-1
        # if nums[left] does not intersect with k, skip this beginning
        # otherwise, we have some right binary digits (as in k's binary representation) and wrong digits
        # and we only can have only wrong 1's (because a[left] intersects with k).
        # For each wrong 1 we can find:
        # - next 0 in that position, this will be first legible right position
        # For each right 1 we can find:
        # - next 0 in that position, this will be first ILLEGIBLE right position
        # So for each number x position we need to store next 0 in that position
        n_digits = 31
        next_zero_idx = [[len(nums)] * len(nums) for _ in range(n_digits)]
        last_zero_idx = [-1] * n_digits
        for cur_i, num in enumerate(nums):
            for pos in range(n_digits):
                if num & (1 << pos) == 0:
                    for prev_i in range(last_zero_idx[pos] + 1, cur_i+1):
                        next_zero_idx[pos][prev_i] = cur_i
                    last_zero_idx[pos] = cur_i
        # print(next_zero_idx)

        ans = 0
        for left in range(len(nums)):
            if nums[left] & k != k:
                continue
            first_idx = left
            after_idx = len(nums)
            for pos in range(n_digits):
                if (1 << pos) & nums[left] != 0:
                    if (1 << pos) & k == 0:
                        first_idx = max(first_idx, next_zero_idx[pos][left])
                    else:
                        after_idx = min(after_idx, next_zero_idx[pos][left])
            # print(left, first_idx, after_idx)
            if after_idx > first_idx:
                ans += after_idx - first_idx

        return ans

class Solution {

    bool check(vector<int>& colors, int i , int k){
