        }
        return true;
    }

    int solve(vector<int>&c, int k){
        vector<int> g;
        int l = c[0];
        int cg = 1;
        bool s = false;

        for (int i = 1; i < c.size(); ++i) {
            if (c[i] == l) {
                g.push_back(cg);
                cg = 1;
                s = true;
            } else {
                cg++;
            }
            l = c[i];
        }
        g.push_back(cg);
        if (g.size() == 1 && g[0] == c.size() && c[0] != c[c.size() - 1] && !s) {
            return c.size();
        }

        if (c[0] != c[c.size() - 1] && g.size() > 1) {
            int lg = g.back();
            g.pop_back();
            g[0] += lg;
        }

        long long r = 0;
        for (int gr : g) {
            r += max(0, gr - (k - 1));
        }

        return (int) r;

    }



