class Solution {
private:
    vector<int> tree;
    int n;

    void buildTree(vector<int>& arr, int treeIndex, int l, int r) {
        if (l == r) {
            tree[treeIndex] = arr[l];
        } else {
            int mid = l + (r - l) / 2;
            int leftChild = 2 * treeIndex + 1;
            int rightChild = 2 * treeIndex + 2;
            buildTree(arr, leftChild, l, mid);
            buildTree(arr, rightChild, mid + 1, r);
            tree[treeIndex] = tree[leftChild] & tree[rightChild];
        }
    }

    int rangeAnd(int treeIndex, int l, int r, int queryL, int queryR) {
        if (l > queryR || r < queryL) {
            return ~0;  // Return all 1s for the AND operation
        }
        if (l >= queryL && r <= queryR) {
            return tree[treeIndex];
        }
        int mid = l + (r - l) / 2;
        int leftChild = 2 * treeIndex + 1;
        int rightChild = 2 * treeIndex + 2;
        int leftAnd = rangeAnd(leftChild, l, mid, queryL, queryR);
        int rightAnd = rangeAnd(rightChild, mid + 1, r, queryL, queryR);
        return leftAnd & rightAnd;
    }

public:
    void build(vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n+1);
        buildTree(arr, 0, 0, n - 1);
    }

    int query(int queryL, int queryR) {
        return rangeAnd(0, 0, n - 1, queryL, queryR);
    }
    long long countSubarrays(vector<int>& v, int k) {
         n = v.size();
        build(v);
        vector<vector<int>> pre(n, vector<int>(30));
        for (int i = 0; i < n; i++) {
            if (i) pre[i] = pre[i - 1];
            for (int b = 0; b < 30; b++) {
                if (((v[i] >> b) & 1) == 0) pre[i][b]++;
            }
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int l = i, r = n - 1, mid, idx1 = -1;
            while(l<=r){
                mid=(l+r)/2;
                if(query(i,mid)>k)l=mid+1;
                else idx1=mid,r=mid-1;
            }
            if(idx1==-1||query(i,idx1)!=k)continue;
            l=idx1,r=n-1;int idx2=-1;
            while(l<=r){
                mid=(l+r)/2;
                if(query(i,mid)<k)r=mid-1;
                else idx2=mid,l=mid+1;
            }
//            cout<<i<<' '<<idx1<<' '<<idx2<<'\n';
            int sz=idx2-idx1+1;
            ans+=sz;
        }

        return ans;
    }
};

