class Solution:

    def countSubarrays(self, nums: List[int], k: int) -> int:
        N = 30
        r_zero, l_one = [-1] * N, [-1] * N
        n = len(nums)
        ans = 0
        for i, num in enumerate(nums):
            ll, rr = 0, i
            for ii in range(N):
                if (1 << ii) & num:  # num ii th bit is 1
                    if l_one[ii] == -1:
                        l_one[ii] = i
                else:
                    l_one[ii] = -1
                    r_zero[ii] = i
                if (1 << ii) & k:  # k ii th bit is 1
                    if l_one[ii] != -1:
                        ll = max(ll, l_one[ii])
                    else:
                        ll = i + 1
                else:
                    if r_zero[ii] != -1:
                        rr = min(rr, r_zero[ii])
                    else:
                        rr = -0x3c3c3c3c3c3c3c3c
            if ll <= rr:
                ans += rr - ll + 1
        return ans

