class Solution {
public:
    int bool_array_to_int(const std::vector<int>& bool_array, int d) {
        int result = 0;
        for (int i = 0; i < bool_array.size(); ++i) {
            result += (bool_array[i] / d) * (1 << i);
        }
        return result;
    }

    long long countSubarrays(vector<int>& nums, int k) {
                int n = nums.size();
        long long ans = 0;
        int r = -1, l = -1;
        int cur = (1 << 30) - 1;
        std::vector<int> bits(31, 0);

        for (int i = 0; i < n; ++i) {
            if ((nums[i] & k) != k) {
                r = l = i;
                cur = (1 << 30) - 1;
                bits.assign(31, 0);
                continue;
            }

            cur &= nums[i];
            for (int j = 0; j < 31; ++j) {
                bits[j] += (nums[i] >> j) & 1;
            }

            if (cur == k) {
                while (r + 1 < i) {
                    for (int j = 0; j < 31; ++j) {
                        bits[j] -= ((nums[r + 1] >> j) & 1);
                    }
                    if (bool_array_to_int(bits, i - r - 1) != k) {
                        for (int j = 0; j < 31; ++j) {
                            bits[j] += ((nums[r + 1] >> j) & 1);
                        }
                        break;
                    } else {
                        ++r;
                    }
                }
                ans += r - l + 1;
            }
        }
        return ans;
    }

};

