    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int start = 0;
        // int end = 0;

        Map<Long, Long> prev = new HashMap<>();
        long andVal = nums[0];

        long subs = 0;

        for(int i = 0; i<n; i++) {
            Map<Long, Long> curr = new HashMap<>();

            if(nums[i] == k)
                subs++;

            curr.put((long) nums[i], 1L);

            for (Map.Entry<Long, Long> entry : prev.entrySet()) {
                long val = entry.getKey();
                long freq = entry.getValue();

                long newAndRes = val&nums[i];

                if(newAndRes == k) 
                    subs+= freq;

                curr.put(newAndRes, curr.getOrDefault(newAndRes, 0L) + freq);
            }

            prev = curr;
        }

        return subs;
    }
}

typedef long long ll;
vector<ll> Mod = {1610612741, 0, 805306457, 402653189, 201326611, 100663319, 50331653, 1000000007, 1000000009};
struct Hash {
    int n{};
    vector<ll> M1, M2, h1, h2;
    ll p1 = 131, p2 = 13331;
    Hash(string& s) {
        Init(s);
    }
    void Init(string& s) {
        if (Mod[1] == 0) change();
        n = s.size();
        work(1, n, s);
    }
    void change() {
        mt19937 rng(chrono::system_clock::now().time_since_epoch().count());
        while (Mod[1] == 0 || Mod[2] == 0) shuffle(Mod.begin(), Mod.end(), rng);
    }
    void work(int st, int len, string& s) {
        M1.resize(len + 1);
        M2.resize(len + 1);
        h1.resize(len + 1);
        h2.resize(len + 1);
        M1[0] = 1;
        M2[0] = 1;
        for (int i = st; i <= len; i++) {
            M1[i] = (M1[i - 1] * p1) % Mod[1];
            h1[i] = (h1[i - 1] * p1 + s[i - st]) % Mod[1];
            M2[i] = (M2[i - 1] * p2) % Mod[2];
            h2[i] = (h2[i - 1] * p2 + s[i - st]) % Mod[2];
        }
    }
    pair<ll, ll> get(int l, int r) {
        ll t1 = ((h1[r] - h1[l - 1] * M1[r - l + 1]) % Mod[1] + Mod[1]) % Mod[1];
        ll t2 = ((h2[r] - h2[l - 1] * M2[r - l + 1]) % Mod[2] + Mod[2]) % Mod[2];
        return {t1, t2};
    }

    pair<ll, ll> mul(pair<ll, ll> l, pair<ll, ll> r, ll len) {
        pair<ll, ll> it;
        l.first *= M1[len] %= Mod[1];
        l.second *= M2[len] %= Mod[2];
        it.first = (l.first + r.first) % Mod[1];
        it.second = (l.second + r.second) % Mod[2];
        return it;
    }
};
class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();
        int ans = 0;
        string str;
        for (int i = 0; i < n; i++) {
            str += colors[i] + '0';
        }
        for (int i = 0; i < n; i++) {
            str += colors[i] + '0';
        }
        string t1, t2;
        for (int i = 0; i < n; i++) {
            t1 += (i % 2) + '0';
            t2 += (1 - i % 2) + '0';
        }
        Hash h1(t1), h2(t2), h3(str);
        for (int i = 0; i < n; i++) {
            auto [a, b] = h3.get(i + 1, i + k);
            auto [t11, t12] = h1.get(1, k);
            auto [t21, t22] = h2.get(1, k);
            if ((a == t11 && b == t12) || (a == t21 && b == t22)) ans++;
        }
        return ans;
    }
};

class Solution {
public:
    using ll = long long;
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<pair<int, int>> valid = {{0, -1}};
        ll ans = 0;
        for (int i = 0; i < n; i++) {
            vector<pair<int, int>> nv = {{nums[i],i}};
            for (auto [val, idx] : valid) {
                int tmp = val & nums[i];
                if (!nv.empty() && nv.back().first == tmp) continue;
                nv.emplace_back(tmp, idx);
            }
            for (int j = 0; j < nv.size(); j++) {
                if (nv[j].first == k) {
                    if (j == nv.size() - 1)
                        ans += nv[j].second + 1;
                    else
                        ans += nv[j].second - nv[j + 1].second;
                }
            }
            valid = nv;
        }
        return ans;
    }
};
